"use client";

import {
  useEffect,
  useRef,
  useState,
  type CSSProperties,
  type FocusEvent as ReactFocusEvent,
  type KeyboardEvent as ReactKeyboardEvent,
  type PointerEvent as ReactPointerEvent,
} from "react";
import {
  Copy,
  GitCommitHorizontal,
  Link2,
  Plus,
  Settings2,
} from "lucide-react";
import { ACTION_NODE_CSS } from "./action-node-css";

/* ── Bencho's constants, unchanged ──────────────────────────
   DOT / SPACING / AIR set the button size, the arc-length gap between
   buttons, and the air the block keeps above and below the card. */
const DOT = 36;
const R = DOT / 2;
const SPACING = DOT + 12;
const BEAT = 90;

const REACH = 25;
const BOUNCE = 20;
const STAGGER = 55;
const COUNT = 4;
const CORNER = 20;

const ACTS = [
  { id: "link", label: "Connect", Icon: Link2 },
  { id: "add", label: "Add a step", Icon: Plus },
  { id: "copy", label: "Duplicate", Icon: Copy },
  { id: "settings", label: "Settings", Icon: Settings2 },
] as const;

const CREW = [
  { id: "mara", name: "Mara Quinn" },
  { id: "ines", name: "Tomás Oliveira" },
  { id: "kai", name: "Lars Andersen" },
] as const;

const ON_STEP = 6;
const NODE = "Node 07";
const SAY =
  "Reads the thread, writes a summary, and posts it back to the channel it came from.";

const clamp = (value: number, lo: number, hi: number) =>
  Math.min(hi, Math.max(lo, value));

/** 0..100 on Bencho's scale, with the used window 20..40 → 11..16px of air. */
const gapPx = (reach: number) => 6 + (clamp(reach, 20, 40) / 100) * 24;

/* The air the block keeps above and below the card, measured at the top of
   the reach window so the box never resizes while the fan moves. */
const AIR = Math.ceil(gapPx(100) + DOT); // 52

const springOf = (tune: number) => ({
  k: 0.08 + (tune / 100) * 0.16,
  d: 0.62 + (tune / 100) * 0.2,
});

/**
 * One spring for every value that settles, ported from Bencho's lab/spring.
 * Frames, not milliseconds: `dt` is in sixtieths and the damping is raised to
 * it, so a dropped frame decays the same energy as the frames it replaced.
 */
function useSpring(target: number, tune = 50, instant = false) {
  const [at, setAt] = useState(target);
  const current = useRef(target);
  const velocity = useRef(0);
  const frame = useRef(0);

  useEffect(() => {
    if (instant) {
      current.current = target;
      velocity.current = 0;
      setAt(target);
      return;
    }

    const { k, d } = springOf(tune);
    let previous = 0;

    const tick = (time: number) => {
      const dt = previous ? clamp((time - previous) / 16.67, 0, 2.5) : 1;
      previous = time;
      velocity.current += (target - current.current) * k * dt;
      velocity.current *= Math.pow(d, dt);
      current.current += velocity.current * dt;

      if (
        Math.abs(target - current.current) < 0.02 &&
        Math.abs(velocity.current) < 0.02
      ) {
        current.current = target;
        velocity.current = 0;
        setAt(target);
        frame.current = 0;
        return;
      }

      setAt(current.current);
      frame.current = requestAnimationFrame(tick);
    };

    frame.current = requestAnimationFrame(tick);

    return () => {
      cancelAnimationFrame(frame.current);
      frame.current = 0;
    };
  }, [target, tune, instant]);

  return at;
}

/**
 * The card outline pushed out by a constant distance: along the top edge,
 * round the corner on a concentric arc, then down the right edge. `s` is arc
 * length from where the corner arc meets the top edge.
 */
function ride(s: number, corner: number, offset: number) {
  const arc = Math.max(0.001, corner + offset);
  const len = (arc * Math.PI) / 2;

  if (s <= 0) return { x: -corner + s, y: -offset };
  if (s >= len) return { x: offset, y: corner + (s - len) };

  const theta = Math.PI / 2 - s / arc;
  return {
    x: -corner + arc * Math.cos(theta),
    y: corner - arc * Math.sin(theta),
  };
}

/**
 * Where a button hides: on the card's diagonal, far enough in that a whole
 * button sits behind the card. A rounded corner needs the longer path.
 */
const hideAt = (corner: number) =>
  corner >= R + 2
    ? corner * Math.SQRT2
    : Math.max(R * Math.SQRT2 + 2, corner * Math.SQRT2 + corner + 2);

const initials = (name: string) =>
  name
    .split(" ")
    .map((word) => word[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();

/**
 * 1:1 port of Bencho's "Action node" card.
 *
 * The card's four actions hide underneath its top-right corner and travel out
 * along an arc struck from that corner. Each button owns a spring; stagger is
 * a delay on each spring's target, opening first-to-last and folding back
 * last-to-first.
 *
 * Deliberate additions for the gallery: the card itself is focusable, so
 * keyboard users can open the fan (the source is pointer-only), and Escape
 * closes it. The avatars use initials because Bencho's photographs are not
 * licensed to travel.
 */
export default function Demo() {
  const n = clamp(Math.round(COUNT), 2, 4);
  const [still, setStill] = useState(false);
  const [on, setOn] = useState(false);
  const [lit, setLit] = useState([false, false, false, false]);
  const timers = useRef<number[]>([]);
  const cardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setStill(query.matches);
    update();
    query.addEventListener("change", update);
    return () => query.removeEventListener("change", update);
  }, []);

  useEffect(() => {
    timers.current.forEach(clearTimeout);
    timers.current = [];

    const gap = still ? 0 : (clamp(STAGGER, 0, 100) / 100) * BEAT;

    for (let i = 0; i < 4; i += 1) {
      // Opening runs first to last; closing runs last to first.
      const place = on ? i : n - 1 - i;
      const at = gap * place;
      const set = () =>
        setLit((previous) => {
          if (previous[i] === on) return previous;
          const next = [...previous];
          next[i] = on;
          return next;
        });

      if (at <= 0) set();
      else timers.current.push(window.setTimeout(set, at));
    }

    return () => {
      timers.current.forEach(clearTimeout);
      timers.current = [];
    };
  }, [on, n, still]);

  /* Four springs, always constructed, as in the source. */
  const p0 = useSpring(lit[0] ? 100 : 0, BOUNCE, still);
  const p1 = useSpring(lit[1] ? 100 : 0, BOUNCE, still);
  const p2 = useSpring(lit[2] ? 100 : 0, BOUNCE, still);
  const p3 = useSpring(lit[3] ? 100 : 0, BOUNCE, still);
  const springAt = [p0, p1, p2, p3];

  const c = clamp(CORNER, 0, 32);
  const offset = gapPx(REACH) + R;
  const middle = ((c + offset) * Math.PI) / 4;
  const spots = Array.from({ length: n }, (_, index) =>
    ride(middle + (index - (n - 1) / 2) * SPACING, c, offset),
  );

  const deep = hideAt(c) / Math.SQRT2;
  const hidden = { x: -deep, y: deep };

  const BLEED = 6;
  const box = spots.reduce(
    (bounds, spot) => ({
      l: Math.min(bounds.l, spot.x - R - BLEED),
      r: Math.max(bounds.r, spot.x + R + BLEED),
      t: Math.min(bounds.t, spot.y - R - BLEED),
      d: Math.max(bounds.d, spot.y + R + BLEED),
    }),
    { l: 0, r: 0, t: 0, d: 0 },
  );
  const padWidth = box.r - box.l;
  const padHeight = box.d - box.t;
  const padX = -box.l;
  const padY = -box.t;

  // Cut the card's quadrant out of the reach pad, so it keeps all of the air
  // and none of the card's surface.
  const biteX = Math.max(0, padX - c);
  const biteY = Math.min(padHeight, padY + c);

  function handlePointerOut(event: ReactPointerEvent<HTMLDivElement>) {
    const to = event.relatedTarget as Node | null;
    if (to && event.currentTarget.contains(to)) return;

    // Keep the fan open while one of its buttons still owns keyboard focus.
    const active = document.activeElement;
    if (
      active &&
      active !== cardRef.current &&
      event.currentTarget.contains(active)
    ) {
      return;
    }

    setOn(false);
  }

  function handleBlur(event: ReactFocusEvent<HTMLDivElement>) {
    const next = event.relatedTarget as Node | null;
    if (!next || !event.currentTarget.contains(next)) setOn(false);
  }

  function handleKeyDown(event: ReactKeyboardEvent<HTMLDivElement>) {
    if (event.key !== "Escape") return;
    setOn(false);
    cardRef.current?.focus({ preventScroll: true });
  }

  return (
    <div className="action-node-demo flex w-full justify-center">
      <style>{ACTION_NODE_CSS}</style>

      <div className="w-full max-w-[368px] [container-type:inline-size]">
        <div className="an-scaler flex justify-center">
          <div
            className="an-nod"
            style={{ paddingBlock: AIR }}
            onPointerEnter={() => setOn(true)}
            onPointerOut={handlePointerOut}
            onPointerCancel={() => setOn(false)}
            onFocus={() => setOn(true)}
            onBlur={handleBlur}
            onKeyDown={handleKeyDown}
          >
            <div
              ref={cardRef}
              className="an-card"
              data-on={on || undefined}
              role="group"
              tabIndex={0}
              aria-label={`${NODE} automation step. Focus or hover to reveal four actions.`}
              style={
                {
                  "--an-r": `${c}px`,
                  "--an-mark-r": `${Math.min(15, c * 0.47).toFixed(2)}px`,
                } as CSSProperties
              }
            >
              <div className="an-top">
                <span className="an-mark" aria-hidden="true">
                  <GitCommitHorizontal size={18} strokeWidth={2} />
                </span>
                <span className="an-name">{NODE}</span>
              </div>

              <p className="an-say">{SAY}</p>

              <div className="an-chain" aria-hidden="true">
                {CREW.map((person) => (
                  <span key={person.id} className="an-link">
                    {initials(person.name)}
                  </span>
                ))}
                <span className="an-more">+{ON_STEP - CREW.length}</span>
              </div>
            </div>

            <div className="an-fan" style={{ top: AIR, right: 0 }}>
              <i
                className="an-reach"
                aria-hidden="true"
                data-on={on || undefined}
                style={{
                  left: box.l,
                  top: box.t,
                  width: padWidth,
                  height: padHeight,
                  clipPath: `polygon(0 0, ${padWidth}px 0, ${padWidth}px ${padHeight}px, ${biteX}px ${padHeight}px, ${biteX}px ${biteY}px, 0 ${biteY}px)`,
                }}
              />

              {ACTS.slice(0, n).map((action, index) => {
                // Not clamped: the spring's overshoot carries the button a
                // little past its spot and back.
                const u = clamp(springAt[index] / 100, 0, 1.4);
                const spot = spots[index];
                const put = (from: number, to: number) =>
                  from + (to - from) * u;

                return (
                  <button
                    key={action.id}
                    className="an-act"
                    type="button"
                    aria-label={action.label}
                    title={action.label}
                    tabIndex={on ? 0 : -1}
                    style={
                      {
                        width: DOT,
                        height: DOT,
                        marginTop: -R,
                        marginLeft: -R,
                        translate: `${put(hidden.x, spot.x)}px ${put(
                          hidden.y,
                          spot.y,
                        )}px`,
                        "--pop": 0.82 + 0.18 * Math.min(u, 1),
                      } as CSSProperties
                    }
                  >
                    <action.Icon size={16} strokeWidth={2} />
                  </button>
                );
              })}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

/**
 * Bencho's `.nod-*` layer, scoped to this demo and resolved from the wall's
 * design tokens to concrete light/dark values.
 *
 * Light:  card #ffffff, ink #17181a, wash .06, edge rgba(23,24,26,.08)
 * Dark:   card #262626, ink #ffffff, wash .053, edge rgba(255,255,255,.08)
 *
 * `.an-act`'s `--pop` is written every animation frame by the spring, so it is
 * deliberately not transitioned; only `--zoom` (hover) is eased. `--zoom` needs
 * `@property` to be interpolatable at all, exactly like Bencho's global
 * registration.
 */
export const ACTION_NODE_CSS = `
@property --zoom {
  syntax: "<number>";
  inherits: false;
  initial-value: 1;
}

.action-node-demo {
  --an-card: #ffffff;
  --an-ink: #17181a;
  --an-ink-rgb: 23, 24, 26;
  --an-ink-3: #5c5b56;
  --an-ink-4: #6f6e68;
  --an-wash: 0.06;
  --an-edge: rgba(23, 24, 26, 0.08);
  --an-focus: 52, 211, 153;
  color: var(--an-ink);
}

.dark .action-node-demo {
  --an-card: #262626;
  --an-ink: #ffffff;
  --an-ink-rgb: 255, 255, 255;
  --an-ink-3: #9a9a9a;
  --an-ink-4: #828282;
  --an-wash: 0.053;
  --an-edge: rgba(255, 255, 255, 0.08);
}

/* Below the width the fan needs (card 272 + 48 of fan), shrink the whole
   composition rather than clipping the buttons against the preview box. */
@container (max-width: 329px) {
  .an-scaler {
    scale: 0.84;
  }
}

.an-nod {
  position: relative;
  width: max-content;
}

.an-card {
  position: relative;
  z-index: 1;
  box-sizing: border-box;
  width: 272px;
  padding: 20px;
  border-radius: var(--an-r, 20px);
  background: var(--an-card);
  color: var(--an-ink);
  box-shadow: 0 0 0 1px var(--an-edge);
  transition: translate 220ms cubic-bezier(0.24, 1.34, 0.38, 1);
}

.an-card[data-on] {
  translate: 0 -1px;
}

.an-card:focus-visible {
  outline: 2px solid rgba(var(--an-focus), 0.65);
  outline-offset: 3px;
}

.an-top {
  display: flex;
  align-items: center;
  gap: 8px;
}

.an-mark {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: var(--an-mark-r, 14px);
  background: rgba(var(--an-ink-rgb), var(--an-wash));
  color: var(--an-ink);
}

.an-name {
  font-size: 16px;
  font-weight: 500;
  letter-spacing: -0.01em;
}

.an-say {
  margin: 13px 0 0;
  font-size: 13px;
  line-height: 1.5;
  color: var(--an-ink-3);
  letter-spacing: 0em;
}

.an-chain {
  display: flex;
  align-items: center;
  margin-top: 16px;
}

.an-link {
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  border-radius: 999px;
  overflow: hidden;
  background: color-mix(in srgb, var(--an-ink) 12%, transparent);
  box-shadow: 0 0 0 2px var(--an-card);
  font-size: 11px;
  font-weight: 500;
  color: var(--an-ink-4);
  letter-spacing: 0em;
  /* The next disc overlaps this one by 6px. With photographs that reads as a
     stack; with the initials fallback it would bite the second letter, so the
     text keeps clear of the overlap. */
  padding-right: 6px;
}

.an-link + .an-link {
  margin-left: -6px;
}

.an-more {
  margin-left: 8px;
  font-size: 11px;
  font-weight: 500;
  color: var(--an-ink-4);
  letter-spacing: 0em;
}

.an-fan {
  position: absolute;
  z-index: 0;
  width: 0;
  height: 0;
}

.an-reach {
  position: absolute;
  pointer-events: none;
}

.an-reach[data-on] {
  pointer-events: auto;
}

.an-act {
  position: absolute;
  top: 0;
  left: 0;
  display: grid;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: var(--an-card);
  color: var(--an-ink);
  box-shadow: 0 0 0 1px var(--an-edge);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  scale: calc(var(--pop, 1) * var(--zoom, 1));
  transition: --zoom 160ms cubic-bezier(0.24, 1.34, 0.38, 1);
}

.an-act:hover {
  --zoom: 1.12;
}

.an-act:focus-visible {
  outline: none;
  box-shadow:
    0 0 0 2px var(--an-card),
    0 0 0 4px rgba(var(--an-focus), 0.7);
}

@media (prefers-reduced-motion: reduce) {
  .an-card {
    transition: none;
  }

  .an-act {
    transition: none;
  }
}
`;

components/card/ascii-wake.code:
"use client";

import { useEffect, useRef, type PointerEvent } from "react";
import {
  createWake,
  WAKE_WIDTH,
  type Wake,
  type WakeOptions,
} from "./ascii-engine";
import { whisk } from "./whisk";

/**
 * A faithful port of Bencho's "ASCII wake" hover block.
 *
 * The cube is a fixed 360 × 240 canvas of monospace cells. Pointer input only
 * writes heat into a Float32Array; the animation loop cools it, picks glyphs
 * and paints, so React never re-renders while the pointer moves.
 */
const OPTIONS: WakeOptions = {
  glyphs: "Classic",
  size: 10,
  reach: 60,
  trail: 1.2,
  pull: 40,
};

export default function Demo() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const surfaceRef = useRef<HTMLDivElement>(null);
  const wakeRef = useRef<Wake | null>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const wake = createWake(canvas);
    wakeRef.current = wake;
    wake.setOptions(OPTIONS);
    wake.resize();

    // Re-read the ink colour when the gallery flips the theme class.
    const observer = new MutationObserver(() => wake.resize());
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    });

    return () => {
      observer.disconnect();
      wake.stop();
      wakeRef.current = null;
    };
  }, []);

  /** Pointer coordinates are mapped back into the canvas' 360 × 240 space. */
  function position(event: PointerEvent<HTMLDivElement>) {
    const surface = surfaceRef.current;
    if (!surface) return { x: 0, y: 0 };
    const rect = surface.getBoundingClientRect();
    const scale = rect.width / WAKE_WIDTH;
    return {
      x: (event.clientX - rect.left) / scale,
      y: (event.clientY - rect.top) / scale,
    };
  }

  function handlePointerEnter(event: PointerEvent<HTMLDivElement>) {
    const { x, y } = position(event);
    wakeRef.current?.enter(x, y);
  }

  function handlePointerMove(event: PointerEvent<HTMLDivElement>) {
    const { x, y } = position(event);
    wakeRef.current?.move(x, y);
  }

  function handlePointerLeave() {
    wakeRef.current?.leave();
  }

  function handlePointerDown(event: PointerEvent<HTMLDivElement>) {
    const { x, y } = position(event);
    wakeRef.current?.ring(x, y);
    whisk();
  }

  return (
    <div className="w-full max-w-[456px] p-6">
      <div
        ref={surfaceRef}
        className="asc relative aspect-[3/2] w-[360px] max-w-full cursor-crosshair touch-none select-none [-webkit-tap-highlight-color:transparent]"
        onPointerEnter={handlePointerEnter}
        onPointerMove={handlePointerMove}
        onPointerLeave={handlePointerLeave}
        onPointerDown={handlePointerDown}
        role="img"
        aria-label="A cube of dots that a pointer drags a wake through"
      >
        <canvas
          ref={canvasRef}
          className="asc-canvas block h-full w-full text-[#17181a] dark:text-white"
          aria-hidden="true"
        />
      </div>
    </div>
  );
}

/**
 * The wake is a grid of numbers, not pixels.
 *
 * Every cell in a 360 × 240 canvas holds a "heat" value. The pointer stamps
 * heat along its path with a soft round falloff; every frame the whole grid
 * cools by the same exponential fraction. A cold cell is a dot whose radius
 * follows the cube mask, a warm cell picks a glyph from a ramp — so the wake
 * visibly thickens under the hand and decays back to dots behind it.
 *
 * The cube itself is not drawn as a shape: three projected faces are tested
 * per cell, and each hit returns a shade that scales the dot radius. That is
 * why the rim reads as an outline and the interior as a lighter field.
 */

export type GlyphSet = "Classic" | "Blocks" | "Dots" | "Binary";

export type WakeOptions = {
  glyphs: GlyphSet;
  /** Dot pitch in CSS pixels. */
  size: number;
  /** Wake radius, 0–100 (mapped to 12–70 CSS pixels). */
  reach: number;
  /** Seconds for the wake to cool. */
  trail: number;
  /** How far glyphs lean toward the pointer, 0–100. */
  pull: number;
};

export const WAKE_WIDTH = 360;
export const WAKE_HEIGHT = 240;

const GLYPHS: Record<GlyphSet, readonly string[]> = {
  Classic: [" ", ".", ":", "-", "=", "+", "*", "#", "%", "@"],
  Blocks: [" ", "·", "░", "▒", "▓", "█"],
  Dots: [" ", "·", "•", "●"],
  Binary: [" ", ".", ":", "0", "1"],
};

const MONO =
  'ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas, monospace';
const DOT_THRESHOLD = 0.04;
const RING_LIFE = 2.2;

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

/** Deterministic hash in [0, 1): the glyph dither must be stable across frames. */
function rand(a: number, b: number) {
  let n = (a * 374761393 + b * 668265263) | 0;
  n = Math.imul(n ^ (n >>> 13), 1274126177);
  return ((n ^ (n >>> 16)) >>> 0) / 4294967296;
}

/**
 * Shade of the isometric cube at (x, y), in canvas-centred coordinates.
 * `light` inverts the ramp so a dark canvas (light theme) keeps the same
 * edge/face contrast as a white one.
 */
function cubeMask(x: number, y: number, light: boolean) {
  const shade = (value: number) =>
    0.35 + 0.65 * clamp(light ? value : 1.09 - value, 0, 1);

  const radius = 112;
  const dx = Math.cos(Math.PI / 6) * radius;
  const half = radius / 2;

  // Top diamond, left face and right face, as projected points.
  const top = [0, -112];
  const upperLeft = [-dx, -56];
  const upperRight = [dx, -56];
  const left = [-dx, half];
  const bottom = [0, radius];

  const barycentric = (a: number[], b: number[], c: number[]) => {
    const v0x = b[0] - a[0];
    const v0y = b[1] - a[1];
    const v1x = c[0] - a[0];
    const v1y = c[1] - a[1];
    const v2x = x - a[0];
    const v2y = y - a[1];
    const den = v0x * v1y - v0y * v1x;
    return [
      (v2x * v1y - v2y * v1x) / den,
      (v0x * v2y - v0y * v2x) / den,
    ];
  };

  const inside = ([u, v]: number[]) => u >= 0 && u <= 1 && v >= 0 && v <= 1;
  /** A third of a cell from the silhouette edge becomes a solid rim dot. */
  const rim = (value: number) => +(value < 0.045);

  let t = barycentric(top, upperRight, upperLeft);
  if (inside(t)) {
    const [u, v] = t;
    return rim(1 - u) || rim(1 - v)
      ? 1
      : shade(0.96 - (0.1 * (u + v)) / 2);
  }

  t = barycentric(upperLeft, [0, 0], left);
  if (inside(t)) {
    const [u, v] = t;
    return rim(u) ? 1 : shade(0.56 - 0.12 * v);
  }

  t = barycentric([0, 0], upperRight, bottom);
  if (inside(t)) {
    const [u, v] = t;
    return rim(u) || rim(v) ? 1 : shade(0.13 - 0.05 * u);
  }

  return 0;
}

export type Wake = ReturnType<typeof createWake>;

export function createWake(canvas: HTMLCanvasElement) {
  let options: WakeOptions = {
    glyphs: "Classic",
    size: 10,
    reach: 60,
    trail: 1.2,
    pull: 40,
  };

  const state = {
    cols: 0,
    rows: 0,
    cw: 0,
    ch: 0,
    ox: 0,
    oy: 0,
    font: "",
    heat: new Float32Array(),
    mask: new Float32Array(),
    hx: -999,
    hy: -999,
    lx: NaN,
    ly: NaN,
    near: 0,
    inside: false,
    rings: [] as { x: number; y: number; t: number }[],
    deal: 0,
    tick: 0,
    raf: 0,
    ratio: 1,
  };

  /** Ink colour is read from CSS so light and dark themes stay in sync. */
  function measure() {
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    state.ratio = dpr;
    canvas.width = Math.round(WAKE_WIDTH * dpr);
    canvas.height = Math.round(WAKE_HEIGHT * dpr);

    const rgb =
      getComputedStyle(canvas).color.match(/[\d.]+/g)?.map(Number) ?? [0, 0, 0];
    const light = rgb[0] * 0.299 + rgb[1] * 0.587 + rgb[2] * 0.114 > 128;

    state.ch = options.size * 0.82;
    state.cw = options.size * 0.62;
    state.cols = Math.floor(WAKE_WIDTH / state.cw - 0.5);
    state.rows = Math.floor(WAKE_HEIGHT / state.ch);
    state.font = `500 ${options.size}px ${MONO}`;
    state.heat = new Float32Array(state.cols * state.rows);
    state.mask = new Float32Array(state.cols * state.rows);

    const ox = (state.ox = (WAKE_WIDTH - state.cols * state.cw) / 2);
    const oy = (state.oy = (WAKE_HEIGHT - state.rows * state.ch) / 2);

    for (let row = 0; row < state.rows; row++) {
      for (let col = 0; col < state.cols; col++) {
        // Odd rows are offset half a cell, which gives the lattice its weave.
        const x =
          ox + (col + 0.5 + (row & 1) * 0.5) * state.cw - WAKE_WIDTH / 2;
        const y = oy + (row + 0.5) * state.ch - WAKE_HEIGHT / 2;
        state.mask[row * state.cols + col] = cubeMask(x, y, light);
      }
    }
  }

  function stamp(px: number, py: number, radius: number, amount: number) {
    const x = px - state.ox;
    const y = py - state.oy;
    const c0 = Math.max(0, Math.floor((x - radius) / state.cw));
    const c1 = Math.min(state.cols - 1, Math.ceil((x + radius) / state.cw));
    const r0 = Math.max(0, Math.floor((y - radius) / state.ch));
    const r1 = Math.min(state.rows - 1, Math.ceil((y + radius) / state.ch));
    const rr = radius * radius;

    for (let row = r0; row <= r1; row++) {
      const dy = (row + 0.5) * state.ch - y;
      for (let col = c0; col <= c1; col++) {
        const dx = (col + 0.5) * state.cw - x;
        const q = (dx * dx + dy * dy) / rr;
        if (q >= 1) continue;
        const falloff = 1 - q;
        const index = row * state.cols + col;
        state.heat[index] = Math.min(
          1,
          state.heat[index] + amount * falloff * falloff,
        );
      }
    }
  }

  const reachRadius = () => 12 + (clamp(options.reach, 0, 100) / 100) * 58;

  function draw() {
    if (!state.cols) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    ctx.setTransform(state.ratio, 0, 0, state.ratio, 0, 0);
    ctx.clearRect(0, 0, WAKE_WIDTH, WAKE_HEIGHT);
    ctx.fillStyle = getComputedStyle(canvas).color;

    const dotRadius = Math.min(state.cw, state.ch) * 0.44;
    ctx.font = state.font;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";

    const ramp = GLYPHS[options.glyphs] ?? GLYPHS.Classic;
    const top = ramp.length - 1;
    const pull = (clamp(options.pull, 0, 100) / 100) * state.near;
    const radius = reachRadius();
    const pullRange = radius * 2;
    const pullRange2 = pullRange * pullRange;
    const nearRange2 = radius * radius;

    const rings = state.rings.map((ring) => {
      const t = ring.t / RING_LIFE;
      const eased = 1 - (1 - t) ** 3;
      return {
        x: ring.x,
        y: ring.y,
        radius: 8 + eased * 260,
        amp: 0.6 * (1 - t) * (1 - t) * Math.min(1, t * 6),
      };
    });

    for (let row = 0; row < state.rows; row++) {
      const y = state.oy + (row + 0.5) * state.ch;
      for (let col = 0; col < state.cols; col++) {
        const index = row * state.cols + col;
        const mask = state.mask[index];
        if (mask <= 0) continue;

        const x = state.ox + (col + 0.5 + (row & 1) * 0.5) * state.cw;
        let heat = state.heat[index];

        // The pointer itself holds a hot spot, even while the hand is still.
        if (state.near > 0.002) {
          const q = ((x - state.hx) ** 2 + (y - state.hy) ** 2) / nearRange2;
          if (q < 1) {
            heat = Math.max(heat, 0.95 * state.near * (1 - q) * (1 - q));
          }
        }

        for (const ring of rings) {
          // Gaussian band: the press sends a widening, fading circle out.
          const q = (Math.hypot(x - ring.x, y - ring.y) - ring.radius) / 24;
          if (q > -2.5 && q < 2.5) heat += ring.amp * Math.exp(-q * q);
        }

        heat *= 0.55 + 0.45 * mask;
        let level = Math.min(1, heat) * top + 0.5;
        if (heat > DOT_THRESHOLD) {
          // Dither the glyph choice so neighbouring cells do not band.
          level +=
            (rand(index, state.deal) - 0.5) * 1.6 * Math.min(1, heat * 2);
        }
        const glyph = clamp(Math.floor(level), 1, top);

        let px = x;
        let py = y;
        if (pull > 0.002) {
          const dx = state.hx - px;
          const dy = state.hy - py;
          const d2 = dx * dx + dy * dy;
          if (d2 < pullRange2) {
            const falloff = 1 - d2 / pullRange2;
            const distance = Math.sqrt(d2) || 1;
            const amount = Math.min(
              distance * 0.6,
              14 * pull * falloff * falloff,
            );
            px += (dx / distance) * amount;
            py += (dy / distance) * amount;
          }
        }

        if (heat <= DOT_THRESHOLD || glyph === 1) {
          ctx.globalAlpha = 1;
          ctx.beginPath();
          ctx.arc(px, py, Math.max(0.45, dotRadius * Math.sqrt(mask)), 0, Math.PI * 2);
          ctx.fill();
          continue;
        }

        ctx.globalAlpha = 1;
        ctx.fillText(ramp[glyph], px, py);
      }
    }
    ctx.globalAlpha = 1;
  }

  function start() {
    if (state.raf) return;
    let last = performance.now();
    const frame = (now: number) => {
      const dt = Math.min(0.05, (now - last) / 1000);
      last = now;

      const cooling = Math.exp((-dt * 3) / Math.max(0.1, options.trail));
      let peak = 0;
      for (let i = 0; i < state.heat.length; i++) {
        const next = state.heat[i] * cooling;
        state.heat[i] = next < 0.003 ? 0 : next;
        if (next > peak) peak = next;
      }

      state.rings = state.rings.filter((ring) => (ring.t += dt) < RING_LIFE);
      state.near += (+!!state.inside - state.near) * (1 - 0.004 ** dt);
      state.tick += dt;
      if (state.tick > 0.07) {
        state.tick = 0;
        state.deal++;
      }

      draw();

      const idle =
        peak === 0 &&
        state.rings.length === 0 &&
        Math.abs(+!!state.inside - state.near) < 0.004;
      state.raf = idle ? 0 : requestAnimationFrame(frame);
    };
    state.raf = requestAnimationFrame(frame);
  }

  function move(x: number, y: number) {
    const radius = reachRadius();
    if (Number.isNaN(state.lx)) {
      state.lx = x;
      state.ly = y;
    }
    // Interpolate along the segment so a fast flick cannot skip cells.
    const distance = Math.hypot(x - state.lx, y - state.ly);
    const steps = Math.max(1, Math.ceil(distance / (radius / 3)));
    for (let i = 1; i <= steps; i++) {
      const t = i / steps;
      stamp(
        state.lx + (x - state.lx) * t,
        state.ly + (y - state.ly) * t,
        radius,
        0.5,
      );
    }
    state.lx = x;
    state.ly = y;
    state.hx = x;
    state.hy = y;
    state.inside = true;
    start();
  }

  return {
    resize() {
      measure();
      draw();
    },
    draw,
    start,
    move,
    enter(x: number, y: number) {
      // A fresh entry must not stamp a line from the last exit point.
      state.lx = NaN;
      state.ly = NaN;
      move(x, y);
    },
    leave() {
      state.inside = false;
      state.lx = NaN;
      start();
    },
    ring(x: number, y: number) {
      state.rings.push({ x, y, t: 0 });
      start();
    },
    setOptions(next: WakeOptions) {
      options = next;
    },
    stop() {
      cancelAnimationFrame(state.raf);
      state.raf = 0;
    },
  };
}

/**
 * One "whisk": a short downward sine sweep with a 50 ms attack, low-passed at
 * 560 Hz. Built only on the first press, so no AudioContext exists until the
 * visitor has made a gesture that allows audio.
 */

let context: AudioContext | null = null;

function audio() {
  if (context) return context;
  try {
    context = new AudioContext();
  } catch {
    return null;
  }
  return context;
}

export function whisk() {
  const ctx = audio();
  if (!ctx) return;
  if (ctx.state !== "running") void ctx.resume();

  const now = ctx.currentTime;
  const duration = 0.13;
  const end = now + duration;

  const osc = ctx.createOscillator();
  osc.type = "sine";
  osc.frequency.setValueAtTime(124, now);
  osc.frequency.exponentialRampToValueAtTime(65, end);

  const gain = ctx.createGain();
  const attack = Math.min(0.05, duration * 0.6);
  gain.gain.setValueAtTime(1e-4, now);
  gain.gain.exponentialRampToValueAtTime(0.067, now + attack);
  gain.gain.exponentialRampToValueAtTime(1e-4, end);

  const filter = ctx.createBiquadFilter();
  filter.type = "lowpass";
  filter.frequency.value = 560;

  osc.connect(filter).connect(gain).connect(ctx.destination);
  osc.start(now);
  osc.stop(end + 0.02);
}

