  border-radius: 50%;
  background: var(--swp-hover-strong);
  color: var(--swp-on);
  font-weight: 600;
  line-height: 1;
}

.swp-stage .swp-flip {
  position: absolute;
  top: 117.5px;
  left: 50%;
  z-index: 2;
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  margin: -20px 0 0 -20px;
  padding: 0;
  border: 0;
  border-radius: 20px;
  background: var(--swp-flip);
  color: var(--swp-on);
  box-shadow: inset 0 0 0 1px var(--swp-edge);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition:
    transform 280ms cubic-bezier(0.3, 1.4, 0.4, 1),
    opacity 180ms;
}

.swp-stage .swp-flip[data-dimmed] {
  transform: scale(0.5);
  opacity: 0;
  pointer-events: none;
  transition:
    transform 160ms,
    opacity 100ms;
}

.swp-stage .swp-flip:not([data-dimmed]):active {
  transform: scale(0.9);
}

.swp-stage .swp-flip:focus-visible {
  outline: 2px solid var(--swp-pick);
  outline-offset: 2px;
}

.swp-stage .swp-flip-arrow {
  display: grid;
  place-items: center;
  transition: transform 600ms cubic-bezier(0.34, 1.56, 0.64, 1);
}

.swp-stage .swp-pick {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px 12px 12px;
  animation: swp-pick-in 220ms 100ms both;
}

.swp-stage .swp-pick[data-leaving] {
  animation: swp-pick-out 160ms both;
  pointer-events: none;
}

.swp-stage .swp-pick-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 32px;
  margin-bottom: 2px;
  padding-left: 12px;
  color: var(--swp-muted);
  font-size: 12px;
  font-weight: 400;
  letter-spacing: 0;
}

.swp-stage .swp-pick-x {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: var(--swp-muted);
  cursor: pointer;
}

.swp-stage .swp-pick-x:hover {
  background: var(--swp-hover);
  color: var(--swp-on);
}

.swp-stage .swp-pick-x:focus-visible {
  outline: 2px solid var(--swp-pick);
  outline-offset: -2px;
}

.swp-stage .swp-pick-row {
  display: flex;
  flex: 1;
  align-items: center;
  gap: 12px;
  min-height: 0;
  padding: 0 12px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: inherit;
  font-family: inherit;
  text-align: left;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.swp-stage .swp-pick-row:hover {
  background: var(--swp-hover);
}

.swp-stage .swp-pick-row:focus-visible {
  outline: 2px solid var(--swp-pick);
  outline-offset: -2px;
}

.swp-stage .swp-pick-sym {
  font-size: 14px;
  font-weight: 500;
  letter-spacing: -0.01em;
}

.swp-stage .swp-pick-name {
  color: var(--swp-muted);
  font-size: 13px;
  font-weight: 400;
  letter-spacing: 0;
}

.swp-stage .swp-pick-on {
  margin-left: auto;
}

@keyframes swp-pick-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes swp-pick-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

.swp-stage .swp[data-reduced="true"] .swp-card,
.swp-stage .swp[data-reduced="true"] .swp-face,
.swp-stage .swp[data-reduced="true"] .swp-flip,
.swp-stage .swp[data-reduced="true"] .swp-flip-arrow,
.swp-stage .swp[data-reduced="true"] .swp-coin {
