  transition-delay: 0ms;
}

.swp-stage .swp[data-reduced="true"] .swp-pick {
  animation: none;
}

@media (prefers-reduced-motion: reduce) {
  .swp-stage .swp-card,
  .swp-stage .swp-face,
  .swp-stage .swp-flip,
  .swp-stage .swp-flip-arrow,
  .swp-stage .swp-coin {
    transition-duration: 1ms;
    transition-delay: 0ms;
  }

  .swp-stage .swp-pick {
    animation: none;
  }
}
