      <path d="m7 15-1.76-1.76a2 2 0 0 0-2.83 2.83l3.32 3.32A6 6 0 0 0 10.24 21H14a8 8 0 0 0 8-8v-1a2 2 0 0 0-4 0" />
    </svg>
