"use client";

import { useEffect, useRef, useState } from "react";
import {
  BAR_ORDER,
  CHIP_ORDER,
  LIMIT,
  formatTokens,
  kindById,
  totalFor,
  valuesFor,
  type KindId,
} from "./engine";
import RollingText from "./rolling-text";
import { cue } from "./sound";
import {
  CONTEXT_METER_CSS,
  GIVE_CHAT,
  GIVE_DEFAULT,
  WAVE_DURATION,
  WAVE_STAGGER,
} from "./styles";
import useReducedMotion from "./use-reduced-motion";

const KIND_COLOUR: Record<KindId, string> = {
  sys: "bg-[#ec4f8c]",
  tools: "bg-[#9a5cf6]",
  files: "bg-[#3d7ef5]",
  chat: "bg-[#1db4cc]",
  mem: "bg-[#2ccb7e]",
};

/**
 * Faithful port of Bencho's "Context meter" (Hover, Bar + Colour defaults).
 *
 * The bar is six flex children: the five kinds ordered by resting size, then
 * the unused room. Hovering a segment or chip lights that kind and shows its
 * own count; compact swaps chat's flex-grow to 30.4 and sends a 760 ms give
 * wave down the bar, staggered 55 ms per segment, over the original sound.
 * The field-of-dots variant is a source prop, not the default here, so it is
 * intentionally not shipped.
 */
export default function Demo() {
  const [compacted, setCompacted] = useState(false);
  const [active, setActive] = useState<KindId | null>(null);
  const [up, setUp] = useState(true);
  const [started, setStarted] = useState(false);
  const reduced = useReducedMotion();

  const barRef = useRef<HTMLDivElement>(null);
  const animations = useRef<Animation[]>([]);
  const reducedRef = useRef(reduced);
  reducedRef.current = reduced;

  const values = valuesFor(compacted);
  const total = totalFor(values);
  const display = active ? values[active] : total;
  const label = active ? kindById(active).name : `of ${LIMIT}K`;

  useEffect(
    () => () => {
      animations.current.forEach((animation) => animation.cancel());
      animations.current = [];
    },
    []
  );

  function playGive() {
    if (reducedRef.current) return;

    animations.current.forEach((animation) => animation.cancel());
    animations.current = [];

    const segments = barRef.current?.querySelectorAll<HTMLElement>(
      "[data-ctx-seg]:not([data-room])"
    );
    if (!segments) return;

    segments.forEach((segment, index) => {
      const give = segment.dataset.kind === "chat" ? GIVE_CHAT : GIVE_DEFAULT;
      const animation = segment.animate(
        [
          { transform: "scale(1, 1)" },
          { transform: `scale(1, ${give})`, offset: 0.38 },
          { transform: "scale(1, 1.03)", offset: 0.72 },
          { transform: "scale(1, 1)" },
        ],
        {
          duration: WAVE_DURATION,
          delay: index * WAVE_STAGGER,
          easing: "cubic-bezier(0.33, 0, 0.2, 1)",
          fill: "both",
        }
      );
      animations.current.push(animation);
    });
  }

  function focusKind(id: KindId | null) {
    if (id !== null) setStarted(true);

    const previous = active ? values[active] : total;
    const next = id ? values[id] : total;
    setUp(next > previous);
    setActive(id);
  }

  function toggle() {
    const next = !compacted;
    const nextValues = valuesFor(next);
    const previous = active ? values[active] : total;
    const shown = active ? nextValues[active] : totalFor(nextValues);

    setUp(shown > previous);
    setStarted(true);
    cue(next ? "compact" : "restore");
    setCompacted(next);
    playGive();
  }

  return (
    <div className="flex w-full items-center justify-center py-6">
      <style>{CONTEXT_METER_CSS}</style>

      <div
        className="ctx-meter w-[309px] max-w-full rounded-[20px] bg-white p-4 text-[#17181a] ring-1 ring-black/[0.08] dark:bg-[#0e0f11] dark:text-white dark:ring-white/[0.08]"
        onPointerLeave={() => setActive(null)}
      >
        <div className="flex items-center justify-between">
          <span className="text-base font-medium leading-5 tracking-[-0.01em]">
            Context
          </span>
          <button
            type="button"
            onClick={toggle}
            className={
              compacted
                ? "ctx-act h-7 rounded-full bg-black/[0.05] px-3 text-[13px] font-medium text-zinc-500 hover:[scale:0.98] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-500/60 focus-visible:ring-offset-2 focus-visible:ring-offset-white active:[scale:0.96] dark:bg-white/[0.08] dark:text-white dark:focus-visible:ring-offset-[#0e0f11]"
                : "ctx-act h-7 rounded-full bg-black/[0.10] px-3 text-[13px] font-medium text-[#17181a] hover:[scale:0.98] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-500/60 focus-visible:ring-offset-2 focus-visible:ring-offset-white active:[scale:0.96] dark:bg-white dark:text-[#0e0f11] dark:focus-visible:ring-offset-[#0e0f11]"
            }
          >
            {compacted ? "Undo" : "Compact"}
          </button>
        </div>

        <div className="mt-3 mb-4 flex items-baseline gap-1.5" aria-live="polite">
          <span className="sr-only">{formatTokens(display)}</span>
          <span className="relative inline-flex text-[30px] font-medium leading-8 tracking-[-0.03em] tabular-nums">
            <RollingText text={formatTokens(display)} up={up} animate={started} />
          </span>
          <span className="text-[13px] text-zinc-500 dark:text-zinc-400">
            {label}
          </span>
        </div>

        <div
          ref={barRef}
          aria-hidden="true"
          className="flex h-10 gap-[3px]"
          onPointerLeave={() => setActive(null)}
        >
          {BAR_ORDER.map((kind, index) => {
            const first = index === 0;
            const dim = active !== null && active !== kind.id;

            return (
              <span
                key={kind.id}
                data-ctx-seg=""
                data-kind={kind.id}
                onPointerEnter={() => focusKind(kind.id)}
                className={`ctx-seg block min-w-[3px] basis-0 ${
                  KIND_COLOUR[kind.id]
                } ${
                  dim ? "opacity-[0.22]" : "opacity-100"
                } ${
                  first ? "rounded-l-[6px] rounded-r-[2px]" : "rounded-[6px]"
                }`}
                style={{ flexGrow: values[kind.id] }}
              />
            );
          })}

          <span
            data-ctx-seg=""
            data-room=""
            onPointerEnter={() => focusKind(null)}
            className={`ctx-seg block min-w-[3px] basis-0 rounded-l-[2px] rounded-r-[6px] bg-black/[0.08] dark:bg-white/[0.08] ${
              active !== null ? "opacity-[0.22]" : "opacity-100"
            }`}
            style={{ flexGrow: LIMIT - total }}
          />
        </div>

        <ul className="sr-only">
          {BAR_ORDER.map((kind) => (
            <li key={kind.id}>
              {kind.name}: {formatTokens(values[kind.id])} of {LIMIT}K
            </li>
          ))}
          <li>
            Unused: {formatTokens(LIMIT - total)} of {LIMIT}K
          </li>
        </ul>

        <div
          className="mt-4 flex flex-wrap gap-1.5"
          onPointerLeave={() => setActive(null)}
        >
          {CHIP_ORDER.map((kind) => (
            <button
              key={kind.id}
              type="button"
              className={`ctx-chip inline-flex h-8 cursor-default items-center gap-2 rounded-full px-3 text-[13px] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-500/60 focus-visible:ring-offset-2 focus-visible:ring-offset-white dark:focus-visible:ring-offset-[#0e0f11] ${
                active === kind.id
                  ? "[scale:0.975] bg-black/[0.12] dark:bg-white/[0.12]"
                  : "bg-black/[0.06] dark:bg-white/[0.06]"
              }`}
              onPointerEnter={() => focusKind(kind.id)}
              onFocus={() => focusKind(kind.id)}
              onBlur={() => setActive(null)}
            >
              <i
                aria-hidden="true"
                className={`block h-2 w-2 rounded-[2px] ${KIND_COLOUR[kind.id]}`}
              />
              {kind.name}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

/**
 * Bencho's context budget, verbatim. Values are thousands of tokens; the bar's
 * `flex-grow` is the raw number, so proportions come straight from this table.
 */
export type KindId = "sys" | "tools" | "files" | "chat" | "mem";

export type Kind = {
  id: KindId;
  name: string;
  /** Token count in thousands, at rest. */
  k: number;
};

export const KINDS: readonly Kind[] = [
  { id: "sys", name: "System", k: 4.2 },
  { id: "tools", name: "Tools", k: 12.8 },
  { id: "files", name: "Files", k: 46.1 },
  { id: "chat", name: "Chat", k: 108.6 },
  { id: "mem", name: "Memory", k: 3.9 },
];

/** The window is 200K tokens. */
export const LIMIT = 200;

/** Compact squeezes chat, and only chat, down to this. */
export const COMPACT_CHAT = 30.4;

/**
 * The bar's order is fixed by the resting sizes (largest first) and does not
 * re-sort when chat shrinks, so compacting reads as one segment giving way.
 */
export const BAR_ORDER: readonly Kind[] = [...KINDS].sort((a, b) => b.k - a.k);

/** Chip order follows the bar. */
export const CHIP_ORDER = BAR_ORDER;

export function valuesFor(compacted: boolean): Record<KindId, number> {
  return {
    sys: 4.2,
    tools: 12.8,
    files: 46.1,
    chat: compacted ? COMPACT_CHAT : 108.6,
    mem: 3.9,
  };
}

export function totalFor(values: Record<KindId, number>): number {
  return KINDS.reduce((sum, kind) => sum + values[kind.id], 0);
}

/** One decimal, e.g. 108.6 → "108.6K". */
export function formatTokens(value: number): string {
  return `${value.toFixed(1)}K`;
}

export function kindById(id: KindId): Kind {
  return KINDS.find((kind) => kind.id === id) ?? KINDS[0];
}

"use client";

import { useEffect, useRef, type CSSProperties } from "react";

/**
 * One wheel per character position. A digit that changes rolls in from the
 * direction the total moved (Bencho uses framer-motion; this is the same
 * 500 ms, 70 ms-per-column entrance expressed as a keyframed span). The
 * source's 160 ms exit blur is omitted; the entering digit covers it.
 */
export default function RollingText({
  text,
  up,
  animate,
}: {
  text: string;
  up: boolean;
  animate: boolean;
}) {
  const previous = useRef(text);
  const previousText = previous.current;

  useEffect(() => {
    previous.current = text;
  }, [text]);

  const chars = text.split("");
  const from = up ? "0.18em" : "-0.18em";

  return (
    <span className="flex leading-none" aria-hidden="true">
      {chars.map((char, index) => {
        const place = chars.length - 1 - index;
        const previousChar = previousText[previousText.length - 1 - place];
        const changed = previousChar !== char;

        if (!/[0-9]/.test(char)) {
          return (
            <span key={`sym-${place}`} className="leading-[1.15]">
              {char}
            </span>
          );
        }

        return (
          <span
            key={`place-${place}`}
            className="inline-block h-[1.15em] overflow-hidden"
          >
            <span
              key={char}
              className={
                animate && changed
                  ? "ctx-digit-roll block leading-[1.15]"
                  : "block leading-[1.15]"
              }
              style={
                animate && changed
                  ? ({
                      "--ctx-from": from,
                      animationDelay: `${index * 70}ms`,
                    } as CSSProperties)
                  : undefined
              }
            >
              {char}
            </span>
          </span>
        );
      })}
    </span>
  );
}

/**
 * Bencho's `compact` and `restore` cues, synthesised locally so the demo stays
 * offline and dependency-free. The original recipes, including the noise
 * sweep, are reproduced part for part.
 */
type Cue = "compact" | "restore";

type Part = {
  hz: number;
  to?: number;
  ms: number;
  gain: number;
  wave?: OscillatorType;
  cut?: number;
  atk?: number;
  at?: number;
  glide?: number;
  q?: number;
  noise?: BiquadFilterType;
  lin?: boolean;
};

const RECIPES: Record<Cue, Part[]> = {
  compact: [
    {
      hz: 2200,
      to: 380,
      ms: 280,
      gain: 0.02,
      q: -3,
      noise: "lowpass",
      atk: 30,
      lin: true,
    },
    {
      hz: 440,
      to: 220,
      ms: 270,
      gain: 0.034,
      wave: "sine",
      cut: 1100,
      atk: 24,
    },
    {
      hz: 196,
      to: 150,
      ms: 110,
      gain: 0.06,
      wave: "triangle",
      cut: 900,
      atk: 2,
      glide: 18,
      at: 280,
    },
    {
      hz: 988,
      ms: 380,
      gain: 0.018,
      wave: "sine",
      cut: 2800,
      atk: 5,
      at: 300,
    },
  ],
  restore: [
    {
      hz: 420,
      to: 1800,
      ms: 260,
      gain: 0.016,
      q: -3,
      noise: "lowpass",
      atk: 40,
      lin: true,
    },
    {
      hz: 220,
      to: 392,
      ms: 250,
      gain: 0.03,
      wave: "sine",
      cut: 1100,
      atk: 30,
    },
    {
      hz: 262,
      ms: 90,
      gain: 0.04,
      wave: "triangle",
      cut: 1100,
      atk: 3,
      at: 270,
    },
  ],
};

let context: AudioContext | null = null;
let noiseBuffer: AudioBuffer | null = null;
const lastPlayed: Record<Cue, number> = { compact: -Infinity, restore: -Infinity };

function audio() {
  if (typeof window === "undefined") return null;
  try {
    context ??= new window.AudioContext();
    if (context.state !== "running") void context.resume();
    return context;
  } catch {
    return null;
  }
}

function noise(ctx: AudioContext) {
  if (noiseBuffer) return noiseBuffer;

  const buffer = ctx.createBuffer(1, Math.floor(ctx.sampleRate * 2), ctx.sampleRate);
  const data = buffer.getChannelData(0);
  for (let i = 0; i < data.length; i += 1) data[i] = Math.random() * 2 - 1;
  noiseBuffer = buffer;
  return buffer;
}

function play(ctx: AudioContext, part: Part) {
  const start = ctx.currentTime + 0.001 + (part.at ?? 0) / 1000;
  const end = start + part.ms / 1000;
  const glideEnd = part.glide ? start + part.glide / 1000 : end;

  let source: AudioBufferSourceNode | OscillatorNode;
  let tail: AudioNode;

  if (part.noise) {
    const sample = ctx.createBufferSource();
    sample.buffer = noise(ctx);
    sample.loop = true;

    const filter = ctx.createBiquadFilter();
    filter.type = part.noise;
    filter.frequency.setValueAtTime(part.hz, start);
    if (part.to) {
      filter.frequency.exponentialRampToValueAtTime(part.to, glideEnd);
    }
    if (part.q !== undefined) filter.Q.value = part.q;

    sample.connect(filter);
    source = sample;
    tail = filter;
  } else {
    const osc = ctx.createOscillator();
    osc.type = part.wave ?? "sine";
    osc.frequency.setValueAtTime(part.hz, start);
    if (part.to) {
      osc.frequency.exponentialRampToValueAtTime(part.to, glideEnd);
    }
    source = osc;
    tail = osc;
  }

  const gain = ctx.createGain();
  const attack = Math.min((part.atk ?? 4) / 1000, (part.ms / 1000) * 0.6);
  gain.gain.setValueAtTime(0.0001, start);
  if (part.lin) {
    gain.gain.linearRampToValueAtTime(part.gain, start + attack);
  } else {
    gain.gain.exponentialRampToValueAtTime(part.gain, start + attack);
  }
  gain.gain.exponentialRampToValueAtTime(0.0001, end);

  if (part.cut) {
    const filter = ctx.createBiquadFilter();
    filter.type = "lowpass";
    filter.frequency.value = part.cut;
    tail.connect(filter);
    tail = filter;
  }

  tail.connect(gain).connect(ctx.destination);
  if (part.noise) {
    (source as AudioBufferSourceNode).start(start, Math.random() * 1.5);
  } else {
    (source as OscillatorNode).start(start);
  }
  source.stop(end + 0.02);
}

export function cue(kind: Cue) {
  const now = typeof performance === "undefined" ? 0 : performance.now();
  if (now - lastPlayed[kind] < 200) return;
  lastPlayed[kind] = now;

  const ctx = audio();
  if (!ctx) return;

  for (const part of RECIPES[kind]) play(ctx, part);
}

/**
 * The only rules Tailwind cannot express: the per-digit wheel entrance and
 * its reduced-motion off switch. Everything else lives on the component.
 */
export const CONTEXT_METER_CSS = `
@keyframes ctx-digit-roll {
  from {
    transform: translateY(var(--ctx-from, 0.18em));
    opacity: 0;
    filter: blur(2px);
  }
  to {
    transform: translateY(0);
    opacity: 1;
    filter: blur(0);
  }
}

.ctx-meter .ctx-digit-roll {
  animation: ctx-digit-roll 500ms cubic-bezier(0.34, 1.45, 0.64, 1) both;
}

/* Segment width and dimming run on different clocks; Tailwind's shorthand
   would collapse both. */
.ctx-meter .ctx-seg {
  transition:
    flex-grow 820ms cubic-bezier(0.65, 0, 0.2, 1),
    opacity 220ms ease;
}

.ctx-meter .ctx-act {
  transition:
    scale 240ms cubic-bezier(0.22, 1, 0.36, 1),
    background-color 220ms ease,
    color 220ms ease;
}

.ctx-meter .ctx-chip {
  transition:
    background-color 160ms ease,
    scale 260ms cubic-bezier(0.34, 1.56, 0.64, 1);
}

@media (prefers-reduced-motion: reduce) {
  .ctx-meter .ctx-digit-roll {
    animation: none;
  }

  .ctx-meter .ctx-seg,
  .ctx-meter .ctx-act,
  .ctx-meter .ctx-chip {
    transition-duration: 1ms;
  }
}
`;

/** Stagger between bar segments when the compact pressure wave rolls through. */
export const WAVE_STAGGER = 55;
export const WAVE_DURATION = 760;
export const GIVE_CHAT = 0.78;
export const GIVE_DEFAULT = 0.93;

"use client";

import { useEffect, useState } from "react";

export default function useReducedMotion() {
  const [reduced, setReduced] = useState(false);

  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener("change", update);
    return () => query.removeEventListener("change", update);
  }, []);

  return reduced;
}

