  --rct-edge: rgba(255, 255, 255, 0.08);
  /* color-mix(in srgb, #ffffff 6%, #262626) and 10% */
  --rct-btn: #333333;
  --rct-btn-hover: #3c3c3c;
}

.roll-demo .rct {
  font-family: inherit;
  display: flex;
  position: relative;
  align-items: center;
  gap: 0;
  padding: 5px;
