          aria-label={data.playing ? "Pause track" : "Play track"}
          onClick={(event) => {
            stop(event);
            onPlay();
          }}
        >
          {data.playing ? <PauseIcon size={24} /> : <PlayIcon size={24} />}
        </button>
        <span aria-hidden="true">
          <SkipForwardIcon size={20} />
        </span>
      </span>
    </span>
