"use client";

import MusicIsland from "./island";

/**
 * Gallery shell for the music island. The block is shown in its default black
 * tone at the default bounce; the gallery's own page background provides the
 * surrounding surface.
 */
export default function Demo() {
  return (
    <div className="mi-stage w-full max-w-[340px]">
      <MusicIsland tone="Black" startOpen />
    </div>
  );
}

import type { SVGProps } from "react";

/**
 * Bencho draws these from its bundled icon set. The paths here are the same
 * outlines, inlined so the demo makes no requests.
 */

type IconProps = SVGProps<SVGSVGElement> & { size?: number };

function Icon({ size = 16, children, ...props }: IconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      focusable="false"
      {...props}
    >
      {children}
    </svg>
  );
}

export function PlayIcon({ size = 24, ...props }: IconProps) {
  return (
    <Icon size={size} fill="currentColor" strokeWidth={0} {...props}>
      <path d="M7 4.5 19 12 7 19.5Z" />
    </Icon>
  );
}

export function PauseIcon({ size = 24, ...props }: IconProps) {
  return (
    <Icon size={size} fill="currentColor" strokeWidth={0} {...props}>
      <path d="M6 4h4v16H6z" />
      <path d="M14 4h4v16h-4z" />
    </Icon>
  );
}

export function PreviousIcon({ size = 20, ...props }: IconProps) {
  return (
    <Icon size={size} fill="currentColor" strokeWidth={0} {...props}>
      <path d="M19 20 9 12 19 4Z" />
      <path d="M5 19V5" />
    </Icon>
  );
}

export function NextIcon({ size = 20, ...props }: IconProps) {
  return (
    <Icon size={size} fill="currentColor" strokeWidth={0} {...props}>
      <path d="M5 4l10 8-10 8Z" />
      <path d="M19 5v14" />
    </Icon>
  );
}

/** The four bars beside the compact artwork; they dance only while playing. */
export function MusicBars({ on }: { on: boolean }) {
  return (
    <span className="mi-bars" data-on={on || undefined} aria-hidden="true">
      <i />
      <i />
      <i />
      <i />
    </span>
  );
}

/**
 * The source ships `/lab/mount.jpg`. This is a local CSS dusk-mountain cover
 * with a palette per playlist entry, so nothing loads from the network.
 */
export function AlbumArt({
  art,
  small = false,
}: {
  art: number;
  small?: boolean;
}) {
  return (
    <span
      className={small ? "mi-art mi-art-s" : "mi-art"}
      data-art={art}
      aria-hidden="true"
    />
  );
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import {
  AlbumArt,
  MusicBars,
  NextIcon,
  PauseIcon,
  PlayIcon,
  PreviousIcon,
} from "./icons";
import { useReducedMotion, useSpringVector } from "./springs";
import { MUSIC_ISLAND_CSS } from "./styles";

export type Tone = "Black" | "White";

/** Compact pill from the source; 150 × 36 with an 18px corner. */
const COMPACT = { width: 150, height: 36, radius: 18 };

/** The opened music card; 300 × 150 with a 42px corner. */
const OPEN = { width: 300, height: 150, radius: 42 };

/** Damping is 34 − 16 × bounce/100 with the block's default bounce of 40. */
const SPRING = { stiffness: 380, damping: 27.6, mass: 0.9 };

type Track = {
  title: string;
  artist: string;
  duration: number;
  art: number;
};

/**
 * The block ships one song ("Soft Focus" on `/lab/mount.jpg`). "Next" needs a
 * destination, so two sibling tracks reuse the same card layout and swap only
 * the local CSS cover palette.
 */
const TRACKS: Track[] = [
  { title: "Soft Focus", artist: "Lumen Park", duration: 214, art: 0 },
  { title: "Glass Hours", artist: "Lumen Park", duration: 186, art: 1 },
  { title: "Night Signal", artist: "Lumen Park", duration: 241, art: 2 },
];

function pad(value: number) {
  return String(value).padStart(2, "0");
}

function clock(seconds: number) {
  return `${Math.floor(seconds / 60)}:${pad(seconds % 60)}`;
}

type PlayerState = { at: number; playing: boolean };

type PanelProps = {
  open: boolean;
  index: number;
  data: PlayerState;
  inert?: boolean;
  onToggle: () => void;
  onSeek: (seconds: number) => void;
  onPrevious: () => void;
  onNext: () => void;
};

/** One layer of content: the compact row, or the full player. */
function Panel({
  open,
  index,
  data,
  inert,
  onToggle,
  onSeek,
  onPrevious,
  onNext,
}: PanelProps) {
  const track = TRACKS[index];
  const progress = Math.min(1, data.at / track.duration);

  if (!open) {
    return (
      <span className="mi-compact">
        <AlbumArt art={track.art} small />
        <MusicBars on={data.playing} />
      </span>
    );
  }

  return (
    <span className="mi-open">
      <span className="mi-music">
        <span className="mi-row">
          <AlbumArt art={track.art} />
          <span className="mi-who">
            <span className="mi-name">{track.title}</span>
            <span className="mi-label">{track.artist}</span>
          </span>
          <span className="mi-grow" />
          <MusicBars on={data.playing} />
        </span>

        <span className="mi-row mi-track">
          <span className="mi-t">{clock(data.at)}</span>
          <span className="mi-rail">
            <span className="mi-fill" style={{ width: `${progress * 100}%` }} />
            <input
              type="range"
              className="mi-seek"
              min={0}
              max={track.duration}
              step={1}
              value={data.at}
              tabIndex={inert ? -1 : undefined}
              aria-label={`Seek in ${track.title}`}
              aria-valuetext={`${clock(data.at)} of ${clock(track.duration)}`}
              onChange={(event) => onSeek(Number(event.target.value))}
            />
          </span>
          <span className="mi-t">
            -{clock(Math.max(0, track.duration - data.at))}
          </span>
        </span>

        <span className="mi-row mi-ctl">
          <button
            type="button"
            className="mi-skip"
            tabIndex={inert ? -1 : undefined}
            aria-label="Restart track"
            onClick={onPrevious}
          >
            <PreviousIcon size={20} />
          </button>
          <button
            type="button"
            className="mi-play"
            tabIndex={inert ? -1 : undefined}
            aria-label={data.playing ? "Pause track" : "Play track"}
            onClick={onToggle}
          >
            {data.playing ? <PauseIcon size={24} /> : <PlayIcon size={24} />}
          </button>
          <button
            type="button"
            className="mi-skip"
            tabIndex={inert ? -1 : undefined}
            aria-label="Next track"
            onClick={onNext}
          >
            <NextIcon size={20} />
          </button>
        </span>
      </span>
    </span>
  );
}

type IslandProps = {
  tone?: Tone;
  startOpen?: boolean;
};

/**
 * Music island, ported from Bencho's press block.
 *
 * Closed it is a 150 × 36 black pill showing the cover and four pink bars.
 * Pressing it springs width, height and radius to 300 × 150 / 42 with the
 * source's 380 / (34 − 16b) / 0.9 spring, while the two content layers
 * crossfade through blur and scale. The player owns a second-by-second clock:
 * play/pause, restart, next and seeking all update the same track position.
 *
 * Approximations: Web Audio click cues are omitted, the photo cover is local
 * CSS art, and "next" cycles a small playlist so the button has a result.
 */
export default function MusicIsland({
  tone = "Black",
  startOpen = false,
}: IslandProps) {
  const reduced = useReducedMotion();
  const [open, setOpen] = useState(startOpen);
  const [pressed, setPressed] = useState(false);
  const [index, setIndex] = useState(0);
  const [data, setData] = useState<PlayerState>({ at: 71, playing: true });
  const toggleRef = useRef<HTMLButtonElement>(null);

  const track = TRACKS[index];

  useEffect(() => {
    // The source advances one second at a time and loops at the track end.
    const timer = window.setInterval(() => {
      setData((current) =>
        current.playing
          ? {
              ...current,
              at: current.at >= track.duration ? 0 : current.at + 1,
            }
          : current,
      );
    }, 1000);
    return () => window.clearInterval(timer);
  }, [track.duration]);

  const shape = open ? OPEN : COMPACT;
  const targets = useMemo(
    () => ({
      width: shape.width,
      height: shape.height,
      radius: shape.radius,
      scale: reduced ? 1 : pressed ? 0.97 : 1,
    }),
    [shape.width, shape.height, shape.radius, pressed, reduced],
  );
  const geometry = useSpringVector(targets, SPRING, reduced);

  /**
   * Two-layer content swap. The old layer leaves immediately; the new one
   * arrives after the source's 60ms beat, so the pill never shows both at
   * full opacity.
   */
  const layerKey = `${open}-${index}`;
  const [tracked, setTracked] = useState({ key: layerKey, open, index });
  const [animated, setAnimated] = useState(false);
  const [leaving, setLeaving] = useState<typeof tracked | null>(null);

  if (tracked.key !== layerKey) {
    setLeaving(tracked);
    setTracked({ key: layerKey, open, index });
    setAnimated(true);
  }

  useEffect(() => {
    if (!leaving) return;
    const timer = window.setTimeout(() => setLeaving(null), reduced ? 0 : 220);
    return () => window.clearTimeout(timer);
  }, [leaving, reduced]);

  const seek = (seconds: number) =>
    setData((current) => ({ ...current, at: seconds }));
  const previous = () => setData((current) => ({ ...current, at: 0 }));
  const next = () => {
    setIndex((current) => (current + 1) % TRACKS.length);
    setData((current) => ({ ...current, at: 0 }));
  };

  const announcement = open
    ? `Now playing ${track.title} by ${track.artist}. ${
        data.playing ? "Playing." : "Paused."
      }`
    : "Music island closed.";

  return (
    <div className="mi mx-auto" data-reduced={reduced ? "true" : undefined}>
      <style>{MUSIC_ISLAND_CSS}</style>

      <div className="mi-top">
        <div
          className="mi-pill"
          data-tone={tone === "White" ? "white" : undefined}
          style={{
            width: geometry.width,
            height: geometry.height,
            borderRadius: geometry.radius,
            transform: `scale(${geometry.scale})`,
          }}
          onPointerDown={() => {
            if (!reduced) setPressed(true);
          }}
          onPointerUp={() => setPressed(false)}
          onPointerLeave={() => setPressed(false)}
          onPointerCancel={() => setPressed(false)}
          onKeyDown={(event) => {
            if (event.key === "Escape" && open) {
              setOpen(false);
              toggleRef.current?.focus();
            }
          }}
        >
          <button
            ref={toggleRef}
            type="button"
            className="mi-toggle"
            aria-expanded={open}
            aria-label={open ? "Close music island" : "Open music island"}
            style={{ borderRadius: geometry.radius }}
            onClick={() => setOpen((value) => !value)}
          />

          <div className="mi-in">
            {leaving && !reduced ? (
              <div
                key={leaving.key}
                className="mi-layer mi-exit"
                aria-hidden="true"
              >
                <Panel
                  open={leaving.open}
                  index={leaving.index}
                  data={data}
                  inert
                  onToggle={() => {}}
                  onSeek={() => {}}
                  onPrevious={() => {}}
                  onNext={() => {}}
                />
              </div>
            ) : null}

            <div
              key={layerKey}
              className={`mi-layer${animated ? " mi-enter" : ""}`}
            >
              <Panel
                open={open}
                index={index}
                data={data}
                onToggle={() =>
                  setData((current) => ({
                    ...current,
                    playing: !current.playing,
                  }))
                }
                onSeek={seek}
                onPrevious={previous}
                onNext={next}
              />
            </div>
          </div>
        </div>
      </div>

      <p className="sr-only" aria-live="polite" aria-atomic="true">
        {announcement}
      </p>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

/**
 * Bencho hands framer-motion one spring for width, height and corner radius.
 * This integrates the same equation locally so the demo stays dependency-free.
 */
export type SpringConfig = { stiffness: number; damping: number; mass: number };

/** Sub-step cap, so a long frame cannot overshoot the integration. */
const STEP = 1 / 240;

/**
 * Moves a set of numbers towards `target` with one shared spring, keeping the
 * pill's three dimensions in phase instead of letting the corners trail.
 * `target` must be memoised by the caller.
 */
export function useSpringVector<T extends Record<string, number>>(
  target: T,
  config: SpringConfig,
  reduced: boolean,
): T {
  const [values, setValues] = useState<T>(target);
  const position = useRef<Record<string, number>>({ ...target });
  const velocity = useRef<Record<string, number>>(
    Object.fromEntries(Object.keys(target).map((key) => [key, 0])),
  );

  useEffect(() => {
    if (reduced) {
      position.current = { ...target };
      setValues({ ...target });
      return;
    }

    const keys = Object.keys(target);
    const { stiffness, damping, mass } = config;
    let frame = 0;
    let previous = 0;

    const tick = (now: number) => {
      const elapsed = previous
        ? Math.min((now - previous) / 1000, 1 / 30)
        : STEP;
      previous = now;

      const steps = Math.max(1, Math.ceil(elapsed / STEP));
      const dt = elapsed / steps;

      for (let step = 0; step < steps; step += 1) {
        for (const key of keys) {
          const offset = position.current[key] - target[key];
          velocity.current[key] +=
            ((-stiffness * offset - damping * velocity.current[key]) / mass) *
            dt;
          position.current[key] += velocity.current[key] * dt;
        }
      }

      let settled = true;
      for (const key of keys) {
        if (
          Math.abs(position.current[key] - target[key]) > 0.01 ||
          Math.abs(velocity.current[key]) > 0.01
        ) {
          settled = false;
          break;
        }
      }

      if (settled) {
        position.current = { ...target };
        velocity.current = Object.fromEntries(keys.map((key) => [key, 0]));
      }

      setValues({ ...position.current } as T);
      if (!settled) frame = requestAnimationFrame(tick);
    };

    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [target, config, reduced]);

  return values;
}

/** Mirrors the media query into React; no browser API runs during render. */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);

  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => setReduced(query.matches);
    sync();
    query.addEventListener("change", sync);
    return () => query.removeEventListener("change", sync);
  }, []);

  return reduced;
}

