.mi-stage .mi[data-reduced="true"] .mi-skip:active {
  scale: 1;
}

.mi-stage .mi[data-reduced="true"] .mi-fill {
  transition: none;
}

.mi-stage .mi[data-reduced="true"] .mi-bars[data-on] i {
  height: 10px;
  animation: none;
}

@media (prefers-reduced-motion: reduce) {
  .mi-stage .mi-enter,
  .mi-stage .mi-exit {
    animation: none;
  }

  .mi-stage .mi-play,
  .mi-stage .mi-skip,
  .mi-stage .mi-bars i {
    transition: none;
  }

  .mi-stage .mi-fill {
    transition: none;
  }

  .mi-stage .mi-bars[data-on] i {
    height: 10px;
    animation: none;
  }
}
`;

