"use client";

import {
  useEffect,
  useRef,
  useState,
  type CSSProperties,
  type KeyboardEvent as ReactKeyboardEvent,
  type PointerEvent as ReactPointerEvent,
} from "react";
import { BalanceChart } from "./balance-chart";
import {
  BASE_GROW,
  BLEND_MS,
  REFRESH_MS,
  RESISTANCE,
  SAMPLE_COUNT,
  SERIES,
  STRETCH,
  THRESHOLD,
  WINDOWS,
  clamp,
  drawPull,
  easeOutQuart,
  formatChange,
  lerp,
  pathFrom,
  plot,
  sample,
  scrubTime,
  sliceSeries,
  splitMoney,
  type Point,
} from "./engine";
import { useReducedMotion, useSpring } from "./motion";
import { RefreshRing } from "./refresh-ring";
import { WindowSwitch } from "./window-switch";

type Phase = "idle" | "hold" | "work";

type Blend = {
  points: Point[];
  value: number;
  change: number;
  pct: number;
  t0: number;
};

/**
 * 1:1 port of Bencho's "Pull to refresh" block.
 *
 * The card is a fixed shell; only the sheet inside moves. Pulling writes a
 * rubber-banded distance (510px asymptote) into the sheet transform and grows
 * the shell's bottom padding by the same saturating amount, so the silhouette
 * stretches instead of sliding. Six droplets fuse into one ring as the pull
 * approaches the 58px threshold and spin while the refresh works.
 *
 * Bencho plays a `drag` cue while scrubbing the chart; the gallery is silent,
 * so that is the only omitted part of the behaviour.
 */
export default function Demo() {
  const reduced = useReducedMotion();
  const [raw, setRaw] = useState(0);
  const [phase, setPhase] = useState<Phase>("idle");
  const [series, setSeries] = useState(0);
  const [view, setView] = useState(WINDOWS.length - 1);
  const [scrub, setScrub] = useState<number | null>(null);
  const [announce, setAnnounce] = useState("");
  const [clock, setClock] = useState(0);

  const sheet = useRef<HTMLDivElement | null>(null);
  const drag = useRef<{
    x: number;
    y: number;
    from: number;
    on: boolean;
  } | null>(null);
  const timer = useRef(0);
  const previousWindow = useRef(view);
  const blend = useRef<Blend | null>(null);
  const blendFrame = useRef(0);
  const armedRef = useRef(false);

  const drawn = drawPull(raw, RESISTANCE);
  const pull = useSpring(
    phase === "work" ? THRESHOLD : phase === "hold" ? drawn : 0,
    58,
    reduced || phase === "hold"
  );

  const held = Math.max(0, pull);
  const progress = clamp(held / THRESHOLD, 0, 1);
  const armed = progress >= 1;
  armedRef.current = armed;

  const stretch =
    pull >= 0 ? STRETCH * Math.tanh(pull / STRETCH) : Math.max(-8, pull);
  const grow = BASE_GROW + stretch;

  const data = sliceSeries(series, view);
  const targetPlot = plot(data);
  const lastIndex = data.length - 1;
  const targetValue = data[lastIndex];
  const targetChange = targetValue - data[0];
  const targetPct = (targetChange / data[0]) * 100;

  const blending = blend.current !== null && !reduced;
  const eased = blending
    ? easeOutQuart(clamp((clock - (blend.current?.t0 ?? 0)) / BLEND_MS, 0, 1))
    : 1;
  const useBlend = blending && eased < 1 && scrub === null;
  const targetSamples = sample(targetPlot);
  const points = useBlend
    ? blend.current!.points.map((point, index) => ({
        x: lerp(point.x, targetSamples[index].x, eased),
        y: lerp(point.y, targetSamples[index].y, eased),
      }))
    : targetSamples;

  let value = targetValue;
  let change = targetChange;
  let pct = targetPct;

  if (scrub !== null) {
    const low = Math.floor(scrub);
    const high = Math.min(lastIndex, Math.ceil(scrub));
    value = lerp(data[low], data[high], scrub - low);
    change = value - data[0];
    pct = (change / data[0]) * 100;
  } else if (useBlend) {
    value = lerp(blend.current!.value, targetValue, eased);
    change = lerp(blend.current!.change, targetChange, eased);
    pct = lerp(blend.current!.pct, targetPct, eased);
  }

  const [whole, decimal] = splitMoney(value);
  const up = change >= 0;
  const shown = useBlend
    ? points[SAMPLE_COUNT - 1]
    : targetPlot.at(scrub ?? lastIndex);
  const path = useBlend ? pathFrom(points) : targetPlot.d;

  const total = SERIES[series % SERIES.length].length;
  const skipped = total - data.length;
  const windowSpan =
    scrub === null
      ? WINDOWS[view].span
      : scrubTime(skipped + scrub, total);

  // Cross-fade the chart when the time window changes. The source eases the
  // previous curve into the next one over 420ms instead of snapping.
  useEffect(() => {
    const previous = previousWindow.current;
    if (previous === view) {
      if (blend.current) {
        blend.current = null;
        setClock(performance.now());
      }
      return;
    }
    previousWindow.current = view;

    const from = sliceSeries(series, previous);
    const previousPlot = plot(from);
    blend.current = {
      points: sample(previousPlot),
      value: from[from.length - 1],
      change: from[from.length - 1] - from[0],
      pct: ((from[from.length - 1] - from[0]) / from[0]) * 100,
      t0: performance.now(),
    };
    setScrub(null);

    cancelAnimationFrame(blendFrame.current);
    if (reduced) {
      blend.current = null;
      return;
    }

    setClock(performance.now());
    const tick = () => {
      const now = performance.now();
      setClock(now);
      if (now - blend.current!.t0 < BLEND_MS) {
        blendFrame.current = requestAnimationFrame(tick);
      } else {
        blend.current = null;
        blendFrame.current = 0;
      }
    };
    blendFrame.current = requestAnimationFrame(tick);

    return () => {
      cancelAnimationFrame(blendFrame.current);
      blendFrame.current = 0;
    };
  }, [reduced, series, view]);

  useEffect(
    () => () => {
      window.clearTimeout(timer.current);
      cancelAnimationFrame(blendFrame.current);
    },
    []
  );

  function refresh() {
    if (phase === "work") return;
    setPhase("work");
    setScrub(null);
    setAnnounce("Refreshing balance");
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => {
      setSeries((current) => current + 1);
      setPhase("idle");
      setAnnounce("Balance updated");
    }, REFRESH_MS);
  }

  function release() {
    const state = drag.current;
    if (!state) return;
    drag.current = null;
    setRaw(0);
    if (!state.on) return;
    if (armedRef.current) refresh();
    else setPhase("idle");
  }

  function handlePointerDown(event: ReactPointerEvent<HTMLDivElement>) {
    if (event.button !== 0) return;
    const element = sheet.current;
    if (!element || phase === "work" || element.scrollTop > 0) return;

    const rect = element.getBoundingClientRect();
    const from = rect.width / (element.offsetWidth || 1) || 1;
    drag.current = { x: event.clientX, y: event.clientY, from, on: false };
  }

  function handlePointerMove(event: ReactPointerEvent<HTMLDivElement>) {
    const state = drag.current;
    if (!state || phase === "work") return;

    const dy = (event.clientY - state.y) / state.from;
    const dx = (event.clientX - state.x) / state.from;

    if (!state.on) {
      if (dy < -4) {
        drag.current = null;
        return;
      }
      if (Math.abs(dx) > 4 && Math.abs(dx) > Math.abs(dy)) {
        drag.current = null;
        return;
      }
      if (dy < 4) return;
      state.on = true;
      event.currentTarget.setPointerCapture?.(event.pointerId);
      setScrub(null);
    }

    setPhase("hold");
    setRaw(Math.max(0, dy));
  }

  function handleKeyDown(event: ReactKeyboardEvent<HTMLDivElement>) {
    if (event.target !== event.currentTarget) return;
    if (event.key !== "Enter" && event.key !== " ") return;
    event.preventDefault();
    refresh();
  }

  function handleScrub(event: ReactPointerEvent<HTMLSpanElement>) {
    if (drag.current?.on || phase === "work") return;
    const rect = event.currentTarget.getBoundingClientRect();
    const fraction = clamp(
      (event.clientX - rect.left) / (rect.width || 1),
      0,
      1
    );
    setScrub(fraction * lastIndex);
  }

  const shellStyle = {
    paddingBottom: grow,
    marginBottom: -grow,
  } as CSSProperties;

  return (
    <div className="flex w-full flex-col items-center justify-center px-2 py-6">
      <style>{`@keyframes ptr-spin { to { rotate: 360deg } }`}</style>

      <div className="relative w-[300px] max-w-full">
        <div
          data-phase={phase}
          data-armed={armed || undefined}
          style={shellStyle}
          className="relative overflow-hidden rounded-[28px] bg-white ring-1 ring-black/[0.06] dark:bg-[#262626] dark:ring-white/[0.08]"
        >
          <RefreshRing phase={phase} progress={progress} reduced={reduced} />

          <div
            ref={sheet}
            role="group"
            tabIndex={0}
            aria-label="Balance card. Pull down, or press Enter, to refresh."
            onKeyDown={handleKeyDown}
            onPointerDown={handlePointerDown}
            onPointerMove={handlePointerMove}
            onPointerUp={release}
            onPointerCancel={release}
            onLostPointerCapture={release}
            style={{
              transform: `translateY(${held.toFixed(2)}px)`,
              touchAction: "pan-x",
            }}
            className="relative z-[2] select-none bg-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-emerald-400/60 dark:bg-[#262626]"
          >
            <div className="px-4 pb-2 pt-4">
              <p className="m-0 text-[30px] font-medium leading-none tracking-[-0.03em] text-[#17181a] [font-variant-numeric:tabular-nums] dark:text-white">
                <span className="mr-[2px]">$</span>
                {whole}
                <span className="text-[20px] font-medium tracking-[-0.02em] opacity-[0.34]">
                  {decimal}
                </span>
              </p>

              <p
                className={`m-0 mt-[9px] flex items-baseline gap-2 text-xs font-normal [font-variant-numeric:tabular-nums] ${
                  up
                    ? "text-[#15803d] dark:text-[#34d17a]"
                    : "text-[#b8431c]"
                }`}
              >
                {formatChange(change)}
                <span aria-hidden="true">·</span>
                {Math.abs(pct).toFixed(1)}%
                <span className="text-[#17181a]/[0.32] dark:text-white/[0.32]">
                  {windowSpan}
                </span>
              </p>

              <BalanceChart
                path={path}
                shown={shown}
                scrub={scrub}
                up={up}
                onScrub={handleScrub}
                onLeave={() => setScrub(null)}
              />

              <WindowSwitch view={view} onChange={setView} />
            </div>
          </div>
        </div>
      </div>

      <span className="sr-only" aria-live="polite" aria-atomic="true">
        {announce}
      </span>
    </div>
  );
}

import type { PointerEvent as ReactPointerEvent } from "react";
import type { Point } from "./engine";

type Props = {
  path: string;
  shown: Point;
  scrub: number | null;
  up: boolean;
  onScrub: (event: ReactPointerEvent<HTMLSpanElement>) => void;
  onLeave: () => void;
};

/**
 * The plot is a scrub surface, not a chart library: the pointer reads a
 * fraction of the box, which is already in screen pixels, so the ratio holds
 * at any zoom. All motion is transform/opacity on the guide and tip.
 */
export function BalanceChart({ path, shown, scrub, up, onScrub, onLeave }: Props) {
  return (
    <span
      aria-hidden="true"
      data-scrub={scrub !== null || undefined}
      onPointerDown={onScrub}
      onPointerMove={onScrub}
      onPointerLeave={onLeave}
      className={`relative my-[22px] mb-[6px] block cursor-crosshair py-[6px] ${
        up ? "text-[#1f9d55]" : "text-[#e5484d] dark:text-[#ff7a4d]"
      }`}
    >
      <svg
        viewBox="0 0 100 40"
        preserveAspectRatio="none"
        className="block h-[92px] w-full overflow-visible"
      >
        <path
          d={path}
          fill="none"
          stroke="currentColor"
          strokeWidth="2.1"
          strokeLinecap="round"
          strokeLinejoin="round"
          vectorEffect="non-scaling-stroke"
        />
      </svg>

      <i
        className={`pointer-events-none absolute bottom-[6px] top-[6px] -ml-px w-px bg-current transition-opacity duration-[160ms] motion-reduce:transition-none ${
          scrub !== null ? "opacity-[0.28]" : "opacity-0"
        }`}
        style={{ left: `${shown.x}%` }}
      />
      <i
        className={`pointer-events-none absolute -ml-[4.5px] -mt-[4.5px] h-[9px] w-[9px] rounded-full bg-white shadow-[0_0_0_2px_currentColor] transition-[scale] duration-[160ms] ease-[cubic-bezier(.24,1.34,.38,1)] motion-reduce:transition-none dark:bg-[#262626] ${
          scrub !== null ? "scale-[1.18]" : "scale-100"
        }`}
        style={{
          left: `${shown.x}%`,
          top: `calc(6px + (100% - 12px) * ${(shown.y / 40).toFixed(4)})`,
        }}
      />
    </span>
  );
}

/**
 * Math and data for the Pull to refresh card.
 *
 * Ported 1:1 from Bencho's Elastic chunk: three fixed balance series, the
 * monotone-cubic chart used to draw them, the rubber-band pull curve and the
 * time-window metadata. Kept out of the component so the interaction file
 * stays readable.
 */

/** Pull resistance default, 0–100. Converts to a 510px asymptote at 50. */
export const RESISTANCE = 50;
/** Distance the gesture must travel before release arms the refresh. */
export const THRESHOLD = 58;
/** How far the bottom of the card can stretch, in px. */
export const STRETCH = 110;
/** Base bottom padding, in px, also used as the resting stretch. */
export const BASE_GROW = 8;
/** How long the fake refresh works before the data changes. */
export const REFRESH_MS = 1150;
/** Cross-fade duration when the chart swaps series. */
export const BLEND_MS = 420;
/** Number of droplets in the refresh ring. */
export const DOTS = 6;

export type WindowId = "1h" | "4h" | "1d";

export type TimeWindow = {
  id: WindowId;
  label: string;
  /** How many points from the end of the series this window shows. */
  take: number;
  span: string;
};

export const WINDOWS: readonly TimeWindow[] = [
  { id: "1h", label: "1H", take: 5, span: "past hour" },
  { id: "4h", label: "4H", take: 17, span: "past 4 hours" },
  { id: "1d", label: "1D", take: 34, span: "today" },
];

/** Balances in GBP, oldest first. */
export const SERIES: readonly (readonly number[])[] = [
  [
    57630.15, 57672.02, 57697.31, 57740.67, 57829.15, 57881.9, 57875.25,
    57871.44, 57841.43, 57824.68, 57957.03, 58078.61, 58095.22, 58136.25,
    58156.95, 58113.65, 58180.3, 58394.72, 58518.55, 58536.23, 58450.89,
    58354.12, 58489.6, 58573.06, 58508.69, 58536.64, 58594.77, 58647.64,
    58668.57, 58682.61, 58720.06, 58743.78, 58784.11, 58834.75,
  ],
  [
    58834.75, 58842.84, 58858.72, 58877.48, 58874.75, 58872.61, 58896.56,
    58906.48, 58893.08, 58922.63, 58981.41, 58963.18, 58940.77, 59001.24,
    59035.63, 59026.34, 59052.16, 59073.47, 59033.25, 59010.92, 58996.54,
    58935.27, 58911.5, 58975.07, 59037.9, 59022.02, 59004.8, 59038.44,
    59055.78, 59056.52, 59072.15, 59078.52, 59088.28, 59102.4,
  ],
  [
    59102.4, 59086.9, 59077.06, 59068.52, 59055.95, 59019.04, 58999.47,
    58975.1, 58903.86, 58916.98, 58989.57, 58926.11, 58763.26, 58683.68,
    58727.54, 58778, 58758.83, 58718.66, 58682.76, 58709.66, 58792.35,
    58782.87, 58692.33, 58598.58, 58598.77, 58672.38, 58655.19, 58615.97,
    58621.85, 58624.03, 58595.53, 58549.14, 58523.68, 58516.05,
  ],
];

export const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

export const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

/** Bencho's rubber band: saturating, so late pixels cost more than early ones. */
export function drawPull(raw: number, resistance = RESISTANCE) {
  const asymptote = 700 - (resistance / 100) * 380;
  return (asymptote * raw) / (asymptote + raw);
}

function formatAmount(value: number) {
  return value.toLocaleString("en-GB", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
}

/** `["$58,834", ".75"]`, so the pence can be dimmed. */
export function splitMoney(value: number): [string, string] {
  const text = formatAmount(value);
  const dot = text.lastIndexOf(".");
  return [text.slice(0, dot), text.slice(dot)];
}

export function formatChange(value: number) {
  return (value < 0 ? "\u2212" : "+") + formatAmount(Math.abs(value));
}

/** Clock label for a scrub position, matching the source's 9:00–17:30 range. */
export function scrubTime(index: number, total: number) {
  const seconds = Math.round(540 + (510 * index) / Math.max(1, total - 1));
  return `${String(Math.floor(seconds / 60)).padStart(2, "0")}:${String(
    seconds % 60
  ).padStart(2, "0")}`;
}

export type Point = { x: number; y: number };

type Segment = { p1: Point; p2: Point; c1: Point; c2: Point };

function segments(points: Point[]): Segment[] {
  return points.slice(0, -1).map((point, index) => {
    const previous = points[index - 1] ?? point;
    const next = points[index + 1];
    const after = points[index + 2] ?? next;
    return {
      p1: point,
      p2: next,
      c1: {
        x: point.x + (next.x - previous.x) / 6,
        y: point.y + (next.y - previous.y) / 6,
      },
      c2: {
        x: next.x - (after.x - point.x) / 6,
        y: next.y - (after.y - point.y) / 6,
      },
    };
  });
}

export function pathFrom(points: Point[]) {
  let d = `M${points[0].x.toFixed(2)} ${points[0].y.toFixed(2)}`;
  for (const segment of segments(points)) {
    d += ` C${segment.c1.x.toFixed(2)} ${segment.c1.y.toFixed(2)} ${segment.c2.x.toFixed(
      2
    )} ${segment.c2.y.toFixed(2)} ${segment.p2.x.toFixed(2)} ${segment.p2.y.toFixed(
      2
    )}`;
  }
  return d;
}

export type Plot = {
  d: string;
  points: Point[];
  at: (index: number) => Point;
};

/**
 * Normalises a series into a 100×40 viewBox and builds a smooth path. The
 * curve needs no zoom correction because it is sampled in the plot's own units.
 */
export function plot(values: readonly number[], height = 40, pad = 4): Plot {
  const min = Math.min(...values);
  const max = Math.max(...values);
  const points = values.map((value, index) => ({
    x: (index / (values.length - 1)) * 100,
    y: height - pad - ((value - min) / (max - min || 1)) * (height - pad * 2),
  }));
  const allSegments = segments(points);

  return {
    d: pathFrom(points),
    points,
    at: (index: number) => {
      const i = clamp(Math.floor(index), 0, allSegments.length - 1);
      const segment = allSegments[i];
      const t = clamp(index - i, 0, 1);
      const u = 1 - t;
      return {
        x:
          u ** 3 * segment.p1.x +
          3 * u * u * t * segment.c1.x +
          3 * u * t * t * segment.c2.x +
          t ** 3 * segment.p2.x,
        y:
          u ** 3 * segment.p1.y +
          3 * u * u * t * segment.c1.y +
          3 * u * t * t * segment.c2.y +
          t ** 3 * segment.p2.y,
      };
    },
  };
}

/** 48 samples along the curve, used to interpolate between two windows. */
export const SAMPLE_COUNT = 48;

export function sample(plotValue: Plot, count = SAMPLE_COUNT): Point[] {
  const last = plotValue.points.length - 1;
  return Array.from({ length: count }, (_, index) =>
    plotValue.at((index / (count - 1)) * last)
  );
}

export function sliceSeries(seriesIndex: number, windowIndex: number) {
  const series = SERIES[seriesIndex % SERIES.length];
  return series.slice(Math.max(0, series.length - WINDOWS[windowIndex].take));
}

export function easeOutQuart(t: number) {
  return 1 - (1 - t) ** 4;
}

import { useEffect, useRef, useState } from "react";
import { clamp } from "./engine";

export function useReducedMotion() {
  const [reduced, setReduced] = useState(false);

  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener("change", update);
    return () => query.removeEventListener("change", update);
  }, []);

  return reduced;
}

/**
 * The source's critically-damped spring: stiffness feeds both the spring
 * constant and the damping. `instant` bypasses it while the finger is down,
 * because the card must track the finger rather than lag behind it.
 */
export function useSpring(target: number, stiffness = 58, instant = false) {
  const [value, setValue] = useState(target);
  const current = useRef(target);
  const velocity = useRef(0);
  const frame = useRef(0);

  useEffect(() => {
    if (instant) {
      current.current = target;
      velocity.current = 0;
      setValue(target);
      return;
    }

    const k = 0.08 + (stiffness / 100) * 0.16;
    const damping = 0.62 + (stiffness / 100) * 0.2;
    let previous = 0;

    const tick = (now: number) => {
      const rate = previous ? clamp((now - previous) / 16.67, 0, 2.5) : 1;
      previous = now;

      velocity.current += (target - current.current) * k * rate;
      velocity.current *= damping ** rate;
      current.current += velocity.current * rate;

      if (
        Math.abs(target - current.current) < 0.02 &&
        Math.abs(velocity.current) < 0.02
      ) {
        current.current = target;
        velocity.current = 0;
        setValue(target);
        frame.current = 0;
        return;
      }

      setValue(current.current);
      frame.current = requestAnimationFrame(tick);
    };

    cancelAnimationFrame(frame.current);
    frame.current = requestAnimationFrame(tick);
    return () => {
      cancelAnimationFrame(frame.current);
      frame.current = 0;
    };
  }, [instant, stiffness, target]);

  return value;
}

import type { CSSProperties } from "react";
import { DOTS } from "./engine";

type Props = {
  phase: "idle" | "hold" | "work";
  progress: number;
  reduced: boolean;
};

const SIZE = 60;
const TOP = 30;

/**
 * Six droplets scattered at rest are drawn into one ring as the pull nears
 * the threshold. While the refresh works the whole box rotates, so the DOM
 * never re-measures a moving rect.
 */
export function RefreshRing({ phase, progress, reduced }: Props) {
  const radius = phase === "work" ? 12 : 12 + 3 - progress * 3;
  const turn = phase === "work" ? 0 : progress * 220;

  const style = {
    width: SIZE,
    height: SIZE,
    marginLeft: -SIZE / 2,
    marginTop: -TOP,
    opacity: phase === "work" ? 1 : progress,
    transform: `scale(${(phase === "work" ? 1 : 0.82 + progress * 0.18).toFixed(
      4
    )})`,
    animation:
      phase === "work" && !reduced
        ? "ptr-spin 3s linear infinite"
        : undefined,
  } as CSSProperties;

  return (
    <div
      aria-hidden="true"
      className="pointer-events-none absolute left-1/2 top-[30px] z-[1] grid place-items-center"
      style={style}
    >
      {Array.from({ length: DOTS }, (_, index) => {
        const angle = (((index / DOTS) * 360 + turn) * Math.PI) / 180;
        return (
          <span
            key={index}
            className="col-start-1 row-start-1 h-1 w-1 rounded-full bg-[#17181a]/[0.32] dark:bg-white/[0.32]"
            style={{
              transform: `translate(${(Math.sin(angle) * radius).toFixed(
                2
              )}px, ${(-Math.cos(angle) * radius).toFixed(2)}px)`,
            }}
          />
        );
      })}
    </div>
  );
}

import { WINDOWS } from "./engine";

type Props = {
  view: number;
  onChange: (index: number) => void;
};

export function WindowSwitch({ view, onChange }: Props) {
  return (
    <div
      role="group"
      aria-label="Time window"
      className="relative mt-4 flex gap-1"
    >
      <span
        aria-hidden="true"
        className="absolute inset-y-0 left-0 rounded-[16px] bg-[#17181a]/[0.06] transition-transform duration-[420ms] ease-[cubic-bezier(.24,1.34,.38,1)] motion-reduce:transition-none dark:bg-white/[0.06]"
        style={{
          width: "calc((100% - 8px) / 3)",
          transform: `translateX(calc(${view} * (100% + 4px)))`,
        }}
      />
      {WINDOWS.map((window, index) => (
        <button
          key={window.id}
          type="button"
          aria-pressed={index === view}
          onClick={() => {
            if (index !== view) onChange(index);
          }}
          className={`relative z-[1] h-8 flex-1 rounded-[16px] border-0 bg-transparent p-0 text-xs font-medium transition-colors duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-400/60 ${
            index === view
              ? "text-[#17181a] dark:text-white"
              : "text-[#17181a]/[0.52] hover:text-[#17181a] dark:text-white/[0.52] dark:hover:text-white"
          }`}
        >
          {window.label}
        </button>
      ))}
    </div>
  );
}

