"use client";

import { useEffect, useReducer, useRef, useState } from "react";
import {
  DEFAULT_PACE,
  DEFAULT_STEPS,
  DEFAULT_WAKE,
  DELAY,
  DOT,
  EASE,
  SPRING,
  WAVE,
  clamp,
  createDots,
  easeOut,
  edgeTransform,
  mix,
  slotRects,
  wakeConfig,
  type Dot,
  type Edge,
  type Wave,
} from "./engine";
import PlayIcon from "./play-icon";
import { cue } from "./sound";

const STEPS = DEFAULT_STEPS;
const PACE = DEFAULT_PACE;
const WAKE = wakeConfig(DEFAULT_WAKE / 100);
const TRACK_WIDTH = slotRects(STEPS, 0)[STEPS - 1][1];

function useReducedMotion() {
  const [reduced, setReduced] = useState(false);

  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener("change", update);
    return () => query.removeEventListener("change", update);
  }, []);

  return reduced;
}

/**
 * Faithful port of Bencho's "Step player" (Press, step-player).
 *
 * Each dot owns a left and a right edge. The current step is expressed purely
 * by which slot is 36px instead of 8px; moving the step tweens every edge with
 * an ease-out, while play advances the fill at `pace` and fires a travelling
 * scaleY wake across the dots that were crossed.
 */
export default function Demo() {
  const [step, setStep] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [, force] = useReducer((n: number) => n + 1, 0);
  const reduced = useReducedMotion();

  const dots = useRef<Dot[]>([]);
  if (dots.current.length === 0) dots.current = createDots(STEPS, 0);
  const progress = useRef(0);
  const wave = useRef<Wave | null>(null);
  const frame = useRef(0);
  const reducedRef = useRef(reduced);
  reducedRef.current = reduced;

  // The loop reads this snapshot, so it always sees the latest state without
  // being restarted on every render.
  const live = useRef({ step, playing, steps: STEPS, pace: PACE, wake: WAKE });
  live.current = { step, playing, steps: STEPS, pace: PACE, wake: WAKE };

  function start() {
    if (frame.current) return;

    let previous = 0;

    const tick = (now: number) => {
      const rate = previous ? clamp((now - previous) / 16.67, 0, 2.5) : 1;
      previous = now;

      const state = live.current;
      let moving = false;

      if (state.playing) {
        progress.current += (rate * 16.67) / (Math.max(0.5, state.pace) * 1000);
        moving = true;

        if (progress.current >= 1) {
          if (state.step < state.steps - 1) {
            progress.current = 0;
            go(state.step + 1, false);
          } else {
            progress.current = 1;
            state.playing = false;
            setPlaying(false);
          }
        }
      }

      const rects = slotRects(state.steps, state.step);

      for (let i = 0; i < dots.current.length; i += 1) {
        const dot = dots.current[i];
        const targets: Array<[Edge, number]> = [
          [dot.l, rects[i][0]],
          [dot.r, rects[i][1]],
        ];

        for (const [edge, target] of targets) {
          if (reducedRef.current) {
            edge.x = target;
            edge.v = 0;
            edge.tw = undefined;
            continue;
          }

          if (edge.tw) {
            const u = clamp((now - edge.tw.t0) / EASE, 0, 1);
            edge.x = mix(edge.tw.from, edge.tw.to, easeOut(u));
            if (u >= 1) edge.tw = undefined;
            moving = true;
            continue;
          }

          edge.v += (target - edge.x) * SPRING.k * rate;
          edge.v *= SPRING.d ** rate;
          edge.x += edge.v * rate;

          if (Math.abs(target - edge.x) < 0.02 && Math.abs(edge.v) < 0.02) {
            edge.x = target;
            edge.v = 0;
          } else {
            moving = true;
          }
        }

        const targetInk =
          i < state.step ? 1 : i === state.step ? progress.current : 0;
        const nextInk = reducedRef.current
          ? targetInk
          : dot.ink + (targetInk - dot.ink) * Math.min(1, 0.22 * rate);

        dot.ink = Math.abs(targetInk - nextInk) < 0.002 ? targetInk : nextInk;
        if (dot.ink !== targetInk) moving = true;
      }

      if (
        wave.current &&
        now - wave.current.t0 <
          EASE + (state.wake.reach + 1) * state.wake.stagger + WAVE
      ) {
        moving = true;
      } else {
        wave.current = null;
      }

      force();
      frame.current = moving ? requestAnimationFrame(tick) : 0;
    };

    frame.current = requestAnimationFrame(tick);
  }

  function go(target: number, resetProgress: boolean) {
    const state = live.current;
    if (target === state.step) return;

    const rects = slotRects(state.steps, target);
    const now = performance.now();

    if (!reducedRef.current) {
      dots.current.forEach((dot, i) => {
        dot.l.tw = { from: dot.l.x, to: rects[i][0], t0: now };
        dot.r.tw = { from: dot.r.x, to: rects[i][1], t0: now };
      });
      wave.current = { t0: now, origin: target, from: state.step };
    }

    state.step = target;
    setStep(target);
    if (resetProgress) progress.current = 0;
    start();
  }

  function toggle() {
    cue("click");
    const state = live.current;

    if (state.playing) {
      state.playing = false;
      setPlaying(false);
      return;
    }

    if (state.step === state.steps - 1 && progress.current >= 1) {
      progress.current = 0;
      go(0, true);
    }

    state.playing = true;
    setPlaying(true);
    start();
  }

  function select(index: number) {
    if (index === live.current.step) return;
    cue("lift");
    go(index, true);
  }

  // Keep the loop entry point stable; `start` itself is redefined each render.
  const startRef = useRef(start);
  startRef.current = start;

  useEffect(() => {
    startRef.current();
  }, [step, playing, reduced]);

  useEffect(
    () => () => {
      cancelAnimationFrame(frame.current);
      frame.current = 0;
    },
    []
  );

  const now = wave.current ? performance.now() : 0;
  const waveValue = reduced ? null : wave.current;

  return (
    <div className="flex w-full items-center justify-center py-6">
      <div
        className="inline-flex flex-col items-center gap-4"
        role="group"
        aria-label={`Step ${step + 1} of ${STEPS}`}
      >
        <div className="flex items-center gap-2">
          <div className="flex items-center justify-center rounded-[18px] bg-white p-[14px] ring-1 ring-[#17181a]/[0.08] dark:bg-[#0e0f11] dark:ring-white/[0.08]">
            <div
              className="relative shrink-0"
              style={{ width: TRACK_WIDTH, height: DOT }}
            >
              {dots.current.map((dot, i) => {
                const width = Math.max(0, dot.r.x - dot.l.x);
                const inkWidth =
                  dot.ink > 0.001
                    ? Math.max(Math.min(DOT, width), width * dot.ink)
                    : 0;

                return (
                  <button
                    key={i}
                    type="button"
                    className="absolute left-0 top-0 h-full cursor-pointer touch-manipulation rounded-full border-0 bg-[#dadada] p-0 after:absolute after:-inset-x-1 after:-inset-y-3 after:content-[''] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#17181a]/[0.45] focus-visible:ring-offset-2 focus-visible:ring-offset-white dark:bg-[#353836] dark:focus-visible:ring-white/[0.45] dark:focus-visible:ring-offset-[#0e0f11]"
                    aria-label={`Step ${i + 1}`}
                    aria-current={i === step ? "step" : undefined}
                    onClick={() => select(i)}
                    style={{
                      width,
                      transform: edgeTransform(dot, i, waveValue, WAKE, now),
                    }}
                  >
                    <span
                      aria-hidden="true"
                      className="absolute left-0 top-0 h-full rounded-full bg-[#17181a] dark:bg-white"
                      style={{
                        width: inkWidth,
                        opacity:
                          i === step ? Math.min(1, dot.ink * 14) : 1,
                      }}
                    />
                  </button>
                );
              })}
            </div>
          </div>

          <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-white ring-1 ring-[#17181a]/[0.08] transition-transform duration-[160ms] ease-[cubic-bezier(.22,1,.36,1)] [&:has(button:active)]:scale-[.96] motion-reduce:transition-none dark:bg-[#0e0f11] dark:ring-white/[0.08]">
            <button
              type="button"
              onClick={toggle}
              aria-label={playing ? "Pause" : "Play"}
              className="grid h-full w-full cursor-pointer place-items-center rounded-full text-[#17181a] transition-colors duration-[160ms] hover:text-[#7f8081] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#17181a]/[0.45] focus-visible:ring-offset-2 focus-visible:ring-offset-white motion-reduce:transition-none dark:text-white dark:hover:text-[#939394] dark:focus-visible:ring-white/[0.45] dark:focus-visible:ring-offset-[#0e0f11]"
            >
              <PlayIcon playing={playing} size={14} still={reduced} />
            </button>
          </div>
        </div>

        <span className="sr-only" aria-live="polite">
          Step {step + 1} of {STEPS}
        </span>
      </div>
    </div>
  );
}

/**
 * Geometry and motion primitives for the Step player port.
 *
 * These mirror Bencho's inline `jt` block exactly: every dot is a pill whose
 * two edges live in their own spring/tween, and the slot width alone decides
 * which dot reads as the current step. Values are hard-coded from the catalog
 * chunk (DOT 8, ACTIVE 36, GAP 8, PAD 14, TOOL 36).
 */

export const DOT = 8;
export const ACTIVE = 36;
export const GAP = 8;
export const PAD = 14;
export const TOOL = 36;

/** Edge ease-out duration, in milliseconds. */
export const EASE = 520;
/** Delay before the wake starts, in milliseconds. */
export const DELAY = 60;
/** One ripple pulse, in milliseconds. */
export const WAVE = 300;

/** x'' = -k(x - target) - d x' with the block's own damping. */
export const SPRING = {
  k: 0.16,
  d: 1 - 2 * Math.sqrt(0.16),
};

export const DEFAULT_STEPS = 5;
export const DEFAULT_PACE = 3;
export const DEFAULT_WAKE = 100;

export const MIN_STEPS = 3;
export const MAX_STEPS = 8;

export function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

export function mix(from: number, to: number, t: number) {
  return from + (to - from) * t;
}

export function easeOut(t: number) {
  return 1 - (1 - t) ** 3;
}

export function easeInOut(t: number) {
  return t < 0.5 ? 4 * t ** 3 : 1 - (-2 * t + 2) ** 3 / 2;
}

export type Edge = {
  x: number;
  v: number;
  tw?: { from: number; to: number; t0: number };
};

export type Dot = {
  l: Edge;
  r: Edge;
  ink: number;
};

export type Wave = {
  t0: number;
  origin: number;
  from: number;
};

export type WakeConfig = {
  amp: number;
  reach: number;
  self: number;
  stagger: number;
};

/**
 * Slot rectangles for `n` dots with `active` holding the wide slot.
 * The track width is constant because only one slot is ever wide.
 */
export function slotRects(n: number, active: number): Array<[number, number]> {
  const rects: Array<[number, number]> = [];
  let x = 0;
  for (let i = 0; i < n; i += 1) {
    const width = i === active ? ACTIVE : DOT;
    rects.push([x, x + width]);
    x += width + GAP;
  }
  return rects;
}

export function createDots(n: number, active: number): Dot[] {
  return slotRects(n, active).map(([left, right], i) => ({
    l: { x: left, v: 0 },
    r: { x: right, v: 0 },
    ink: i < active ? 1 : 0,
  }));
}

/** Wake knobs for a 0..1 amount: amplitude, reach, landing squash and stagger. */
export function wakeConfig(amount: number): WakeConfig {
  return {
    amp: mix(0.26, 0.34, amount),
    reach: 1 + Math.round(amount * 7),
    self: mix(-0.7, 0.3, amount),
    stagger: mix(70, 55, amount),
  };
}

/**
 * The wave is a travelling sine. Dots between the old and new step stand up in
 * the order they were crossed; the landing dot answers after the last one.
 */
export function edgeTransform(
  dot: Dot,
  index: number,
  wave: Wave | null,
  config: WakeConfig,
  now: number
) {
  let scale = 1;

  if (wave) {
    const span = Math.abs(wave.origin - wave.from);
    const flat = Math.max(0, span - config.reach);
    const lo = Math.min(wave.from, wave.origin);
    const hi = Math.max(wave.from, wave.origin);

    let delay = -1;
    let self = 1;

    if (index === wave.origin) {
      delay = Math.min(span, config.reach) * config.stagger;
      self = config.self;
    } else if (index >= lo && index <= hi) {
      const distance = Math.abs(index - wave.from);
      if (span - distance <= config.reach) {
        delay = (distance - flat) * config.stagger;
      }
    }

    if (delay >= 0) {
      const u = (now - wave.t0 - DELAY - delay) / WAVE;
      if (u > 0 && u < 1) {
        scale = 1 + Math.sin(Math.PI * u) * config.amp * self;
      }
    }
  }

  return `translateX(${dot.l.x.toFixed(2)}px) scaleY(${scale.toFixed(3)})`;
}

"use client";

import { useEffect, useRef, useState } from "react";
import { clamp, easeInOut, mix } from "./engine";

/** The block's play/pause mark: two rounded quadrilaterals that morph. */
const PLAY_LEFT = [6.5, 4, 13.25, 8, 13.25, 16, 6.5, 20];
const PAUSE_LEFT = [6, 4, 10, 4, 10, 20, 6, 20];
const PLAY_RIGHT = [13.25, 8, 20, 12, 20, 12, 13.25, 16];
const PAUSE_RIGHT = [14, 4, 18, 4, 18, 20, 14, 20];

function path(from: number[], to: number[], t: number) {
  let d = "";
  for (let i = 0; i < 8; i += 2) {
    d += `${i ? "L" : "M"}${mix(from[i], to[i], t).toFixed(2)} ${mix(
      from[i + 1],
      to[i + 1],
      t
    ).toFixed(2)}`;
  }
  return `${d}Z`;
}

/**
 * 300 ms tween from play (1) to pause (0), matching the Sound block's Mark.
 * Reduced motion snaps instead of animating.
 */
function useMorph(target: number, still: boolean) {
  const [value, setValue] = useState(target);
  const current = useRef(target);

  useEffect(() => {
    if (still) {
      current.current = target;
      setValue(target);
      return;
    }

    const from = current.current;
    if (from === target) return;

    const start = performance.now();
    let frame = 0;

    const tick = (now: number) => {
      const t = Math.min(1, (now - start) / 300);
      current.current = from + (target - from) * easeInOut(t);
      setValue(current.current);
      frame = t < 1 ? requestAnimationFrame(tick) : 0;
    };

    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [target, still]);

  return value;
}

export default function PlayIcon({
  playing,
  size = 14,
  still = false,
}: {
  playing: boolean;
  size?: number;
  still?: boolean;
}) {
  const t = useMorph(playing ? 0 : 1, still);
  const wave = Math.sin(clamp(t, 0, 1) * Math.PI);
  const shift = 1.6 * wave;
  const rotate = (playing ? -9 : 9) * wave;

  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      aria-hidden="true"
      fill="currentColor"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinejoin="round"
      strokeLinecap="round"
      style={{
        transformOrigin: "50% 50%",
        transform: `rotate(${rotate}deg) scale(${1 - 0.13 * wave}, ${
          1 + 0.11 * wave
        })`,
      }}
    >
      <path d={path(PAUSE_LEFT, PLAY_LEFT, t)} transform={`translate(${shift} 0)`} />
      <path d={path(PAUSE_RIGHT, PLAY_RIGHT, t)} transform={`translate(${-shift} 0)`} />
    </svg>
  );
}

/**
 * Two cues from Bencho's shared sound kit, synthesised locally so the demo
 * stays offline and dependency-free. The original recipes are:
 *
 *   click: 196 → 130 Hz, 150 ms, sine, gain .07, low-pass 900 Hz
 *   lift:  660 → 720 Hz,  38 ms, sine, gain .028
 */
type Cue = "click" | "lift";

type Part = {
  hz: number;
  to?: number;
  ms: number;
  gain: number;
  cut?: number;
  atk?: number;
};

const RECIPES: Record<Cue, Part[]> = {
  click: [{ hz: 196, to: 130, ms: 150, gain: 0.07, cut: 900 }],
  lift: [{ hz: 660, to: 720, ms: 38, gain: 0.028 }],
};

let context: AudioContext | null = null;

function audio() {
  if (typeof window === "undefined") return null;
  try {
    context ??= new window.AudioContext();
    if (context.state !== "running") void context.resume();
    return context;
  } catch {
    return null;
  }
}

function play(part: Part) {
  const ctx = audio();
  if (!ctx || ctx.state !== "running") return;

  const start = ctx.currentTime + 0.001;
  const end = start + part.ms / 1000;
  const hold = start + Math.min((part.atk ?? 4) / 1000, (part.ms / 1000) * 0.6);

  const osc = ctx.createOscillator();
  osc.type = "sine";
  osc.frequency.setValueAtTime(part.hz, start);
  if (part.to) {
    osc.frequency.exponentialRampToValueAtTime(part.to, end);
  }

  const gain = ctx.createGain();
  gain.gain.setValueAtTime(0.0001, start);
  gain.gain.exponentialRampToValueAtTime(part.gain, hold);
  gain.gain.exponentialRampToValueAtTime(0.0001, end);

  let tail: AudioNode = osc;
  if (part.cut) {
    const filter = ctx.createBiquadFilter();
    filter.type = "lowpass";
    filter.frequency.value = part.cut;
    tail.connect(filter);
    tail = filter;
  }

  tail.connect(gain).connect(ctx.destination);
  osc.start(start);
  osc.stop(end + 0.02);
}

export function cue(kind: Cue) {
  for (const part of RECIPES[kind]) play(part);
}

