  --upl-ink: #f4f3f1;
  --upl-ink-3: #9a9a9a;
  --upl-signal: #8b96ff;
  --upl-ok: #3fb950;
  --upl-red: #ff6369;
}

.upl-input {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.upl-zone-wrap {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: center;
  height: 176px;
}

.upl-zone {
  position: relative;
  flex: none;
  align-self: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  width: 100%;
  height: 176px;
  padding: 0 16px;
  border-radius: var(--upl-r);
  border: 1px solid color-mix(in srgb, var(--upl-ink) 10%, transparent);
  background: var(--upl-slab);
  overflow: hidden;
  transition:
