  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 10px;
  background: color-mix(in srgb, var(--upl-ink) 6%, var(--upl-slab));
  color: color-mix(in srgb, var(--upl-ink) 72%, var(--upl-slab));
  transition:
    translate 0.42s cubic-bezier(0.24, 1.34, 0.38, 1),
