}
.upl-bar {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: var(--upl-signal);
  transform-origin: 0 50%;
}
.upl-roll {
  display: inline-flex;
  height: 1em;
  overflow: hidden;
  line-height: 1em;
  font-variant-numeric: tabular-nums;
  vertical-align: baseline;
}
.upl-roll-col {
  display: inline-block;
  height: 1em;
  overflow: hidden;
}
.upl-roll-strip {
  display: flex;
  flex-direction: column;
  transition: transform 0.22s cubic-bezier(0.24, 1.34, 0.38, 1);
}
.upl-roll-strip > span {
  display: block;
  height: 1em;
  line-height: 1em;
}
.upl-pct {
  margin-left: 1px;
}

.upl-end {
  display: flex;
  flex: none;
  align-items: center;
  gap: 4px;
