.upl-act {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  padding: 0;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--upl-ink-3);
  cursor: pointer;
  transition:
    background-color 0.18s ease,
    color 0.18s ease;
}
.upl-act:hover {
  background: color-mix(in srgb, var(--upl-ink) 7%, transparent);
