}
.upl-act:focus-visible {
  outline: 2px solid var(--upl-signal);
  outline-offset: 1px;
}

.upl-error {
  margin: -4px 0 0;
  color: var(--upl-red);
  font-size: 12px;
  line-height: 1.4;
}

.upl-tray {
  display: flex;
  justify-content: center;
  gap: 20px;
}
.upl-slot {
  position: relative;
  width: 76px;
  height: 75px;
  transition: opacity 0.22s ease;
}
.upl-slot[data-empty] {
  opacity: 0;
  pointer-events: none;
}
.upl-file {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  width: 76px;
  padding: 4px 0 0;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: color-mix(in srgb, var(--upl-ink) 72%, var(--upl-slab));
  font: inherit;
  font-size: 11px;
  cursor: grab;
  touch-action: none;
  transition: color 0.18s ease;
}
.upl-file:hover {
  color: var(--upl-ink);
}
.upl-file:active {
  cursor: grabbing;
}
.upl-file:focus-visible {
  outline: 2px solid var(--upl-signal);
  outline-offset: 2px;
}
.upl-file .upl-page {
  flex: none;
  overflow: visible;
}
.upl-label {
  max-width: 76px;
  overflow: hidden;
  font-size: 11px;
  line-height: 1.2;
  letter-spacing: 0;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.upl-page-line {
  fill: none;
  stroke: color-mix(in srgb, var(--upl-ink) 32%, var(--upl-slab));
  stroke-width: 1.5px;
}
.upl-page-ext {
  fill: #ffffff;
  font-family: inherit;
  font-weight: 500;
  letter-spacing: 0;
}

@keyframes upl-march {
  to {
    stroke-dashoffset: -22;
  }
}
@keyframes upl-gulp {
  0% {
    scale: 1.02;
  }
  35% {
    scale: 0.985;
  }
  70% {
    scale: 1.006;
  }
  to {
    scale: 1;
  }
}
@keyframes upl-open {
  40% {
    scale: 1.08;
  }
}
@keyframes upl-land {
  0% {
    opacity: 0;
    translate: 0 10px;
    scale: 0.85;
  }
}
@keyframes upl-pop {
  0% {
    scale: 0;
  }
}
@keyframes upl-shake {
  0%,
  100% {
    translate: 0;
  }
  20% {
    translate: -7px;
  }
  40% {
    translate: 6px;
  }
  60% {
    translate: -4px;
  }
  80% {
    translate: 2px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .upl-zone,
  .upl-icon,
  .upl-slot,
  .upl-file,
  .upl-act,
  .upl-dash rect,
  .upl-roll-strip {
    transition: none;
  }
  .upl-zone[data-over] {
    scale: 1;
  }
  .upl-zone[data-gulp],
  .upl-zone[data-gulp] .upl-icon,
  .upl-zone[data-shake],
  .upl-zone[data-over] .upl-dash rect,
  .upl-now,
  .upl-tick {
    animation: none;
  }
  .upl-dash rect {
    stroke-dashoffset: 0;
  }
}
`;

/*
 * Bencho's "Upload dropzone" defaults, unchanged: a 5 MB cap, speed 50,
 * bounce 40, corner 20, and the two tray sheets with their sizes and tints.
 */
export const MAX_MB = 5;
export const MAX_BYTES = MAX_MB * 1_000_000;
export const SPEED = 50;
export const BOUNCE = 40;
export const CORNER = 20;
export const DIGITS = "0123456789".split("");
export const SAMPLE_MIME = "application/x-upload-dropzone-sample";

/** The block's retort cycle after the first refusal. */
export const REFUSALS = [
  "Still 12.6 MB. It didn't shrink.",
  "Pushing harder won't help",
  "Have you tried compressing it?",
  "The box is full of excuses now",
  "No.",
];

export type UploadFile = {
  id: string;
  name: string;
  size: number;
  ext: string;
  tint: string;
};

export const SAMPLES: readonly UploadFile[] = [
  {
    id: "sample-mood",
    name: "mood.png",
    size: 2_400_000,
    ext: "PNG",
    tint: "#079455",
  },
  {
    id: "sample-demo",
    name: "demo.mp4",
    size: 12_600_000,
    ext: "MP4",
    tint: "#155EEF",
  },
];

const TINTS: Record<string, string> = {
  PNG: "#079455",
  JPG: "#079455",
  JPEG: "#079455",
  GIF: "#079455",
  WEBP: "#079455",
  SVG: "#079455",
  MP4: "#155EEF",
  MOV: "#155EEF",
  WEBM: "#155EEF",
  MP3: "#9A5BFF",
  WAV: "#9A5BFF",
  PDF: "#E5484D",
  ZIP: "#B54708",
  RAR: "#B54708",
};

/** Source format: one decimal above 1 MB, whole KB below. */
export function formatSize(bytes: number) {
  return bytes >= 1_000_000
    ? `${(bytes / 1_000_000).toFixed(1)} MB`
    : `${Math.round(bytes / 1_000)} KB`;
}

export function describeFile(name: string, size: number, id: string) {
  const extension = name.includes(".") ? (name.split(".").pop() ?? "") : "";
  const ext =
    extension
      .replace(/[^a-z0-9]/gi, "")
      .slice(0, 4)
      .toUpperCase() || "FILE";

  return { id, name, size, ext, tint: TINTS[ext] ?? "#52525B" };
}

"use client";

import { useEffect, useState } from "react";
import { DIGITS } from "./upload-data";

export function usePrefersReducedMotion() {
  const [reduced, setReduced] = useState(false);

  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener("change", update);
    return () => query.removeEventListener("change", update);
  }, []);

  return reduced;
}

/** Bencho's odometer percent: each column is a 0–9 strip slid to its digit. */
export function RollingPercent({ value }: { value: number }) {
  const text = String(Math.round(value)).split("");

  return (
    <span className="upl-roll" aria-hidden="true">
      {text.map((digit, index) => (
        <span className="upl-roll-col" key={text.length - index}>
          <span
            className="upl-roll-strip"
            style={{ transform: `translateY(${-Number(digit)}em)` }}
          >
            {DIGITS.map((entry) => (
              <span key={entry}>{entry}</span>
            ))}
          </span>
        </span>
      ))}
      <span className="upl-pct">%</span>
    </span>
  );
}

