"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import type { CSSProperties } from "react";
import { useReducedMotion } from "./springs";
import { ToastRow } from "./toast-row";
import {
  EXIT_MS,
  PRESETS,
  SHOWN,
  STACK_HEIGHT,
  TOAST_WIDTH,
  type Toast,
} from "./toast-data";

function createInitialToasts(): Toast[] {
  return PRESETS.slice(0, SHOWN).map((toast, id) => ({ ...toast, id }));
}

/**
 * A 1:1 port of Bencho's "Toast stack" block.
 *
 * Three toasts rest as a centred pile; pointing at the region (or moving focus
 * into it) fans them into a list with one spring each. Dismissing a row tweens
 * it out to the right, then swaps in the next toast from the block's cycle at
 * the front, so the new arrival springs down from above. `Retry` resolves the
 * declined payment in place.
 *
 * The source's four Web Audio cues and framer-motion are not ported; the same
 * spring is integrated in `springs.ts`, matching the rest of this gallery. Its
 * white pane edge (40% in light, 20% in dark) is kept, and the demo sits on the
 * light surface Bencho stages the block on so the front row stays legible.
 */
export default function ToastStack() {
  const reduced = useReducedMotion();
  const [toasts, setToasts] = useState<Toast[]>(createInitialToasts);
  const [exitingId, setExitingId] = useState<number | null>(null);
  const [open, setOpen] = useState(false);
  const [announcement, setAnnouncement] = useState("");

  const timers = useRef<number[]>([]);
  const nextIndex = useRef(SHOWN);

  useEffect(
    () => () => {
      for (const timer of timers.current) window.clearTimeout(timer);
      timers.current = [];
    },
    [],
  );

  const dismiss = useCallback(
    (id: number) => {
      if (exitingId !== null) return;
      const toast = toasts.find((entry) => entry.id === id);
      setExitingId(id);

      const timer = window.setTimeout(() => {
        timers.current = timers.current.filter((entry) => entry !== timer);
        const index = nextIndex.current;
        nextIndex.current += 1;
        const next = PRESETS[index % PRESETS.length];
        setToasts((current) => [
          { ...next, id: index },
          ...current.filter((entry) => entry.id !== id),
        ]);
        setExitingId(null);
        setAnnouncement(
          `${toast?.title ?? "Notification"} dismissed. ${next.title} arrived.`,
        );
      }, EXIT_MS);

      timers.current.push(timer);
    },
    [exitingId, toasts],
  );

  const resolve = useCallback((id: number) => {
    setToasts((current) =>
      current.map((toast) =>
        toast.id === id
          ? {
              ...toast,
              kind: "success",
              title: "Payment complete",
              body: "Your card was charged.",
              action: undefined,
            }
          : toast,
      ),
    );
    setAnnouncement("Payment complete. Your card was charged.");
  }, []);

  return (
    <div className="flex w-full justify-center">
      <div className="w-full max-w-[340px] p-5">
        <div
          role="region"
          aria-label="Notifications"
          data-open={open || undefined}
          className="relative mx-auto"
          style={
            {
              width: TOAST_WIDTH,
              height: STACK_HEIGHT,
              maxWidth: "100%",
            } as CSSProperties
          }
          onPointerOver={() => {
            if (!open) setOpen(true);
          }}
          onPointerOut={(event) => {
            const next = event.relatedTarget;
            if (next instanceof Node && event.currentTarget.contains(next))
              return;
            // Keep the stack open while focus is inside, so a tucked row can
            // never become aria-hidden around the focused button.
            const active = document.activeElement;
            if (active instanceof Node && event.currentTarget.contains(active))
              return;
            setOpen(false);
          }}
          onPointerCancel={() => setOpen(false)}
          onFocus={() => {
            if (!open) setOpen(true);
          }}
          onBlur={(event) => {
            const next = event.relatedTarget;
            if (next instanceof Node && event.currentTarget.contains(next))
              return;
            setOpen(false);
          }}
        >
          {toasts.map((toast, depth) => (
            <ToastRow
              key={toast.id}
              toast={toast}
              depth={depth}
              open={open}
              exiting={exitingId === toast.id}
              reduced={reduced}
              onDismiss={dismiss}
              onResolve={resolve}
            />
          ))}
        </div>

        <p className="sr-only" aria-live="polite" aria-atomic="true">
          {announcement}
        </p>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

/**
 * The single spring Bencho gives every toast: stiffness 380, damping 34,
 * mass 1. Integrated semi-implicitly in seconds, sub-stepped so a dropped
 * frame cannot make the bounce explode; the catalog copy of the block lists
 * 320 / 30, but the shipped component uses these values.
 */
const STIFFNESS = 380;
const DAMPING = 34;
const MASS = 1;

/** Integration step; one frame is split into steps no longer than this. */
const STEP = 1 / 240;

export type Pose = { y: number; scale: number };

/**
 * Moves `y` and `scale` towards their targets with Bencho's spring. Each row
 * owns one loop; rows are keyed by toast id, so reordering rows keeps their
 * in-flight positions and the stack reshuffles smoothly.
 */
export function useSpringPose(
  targetY: number,
  targetScale: number,
  initialY: number,
  reduced: boolean,
): Pose {
  const [pose, setPose] = useState<Pose>({ y: initialY, scale: 1 });
  const position = useRef<Pose>({ y: initialY, scale: 1 });
  const velocity = useRef<Pose>({ y: 0, scale: 0 });

  useEffect(() => {
    if (reduced) {
      position.current = { y: targetY, scale: targetScale };
      velocity.current = { y: 0, scale: 0 };
      setPose({ y: targetY, scale: targetScale });
      return;
    }

    let frame = 0;
    let previous = 0;

    const tick = (now: number) => {
      const elapsed = previous
        ? Math.min((now - previous) / 1000, 1 / 30)
        : STEP;
      previous = now;

      const steps = Math.max(1, Math.ceil(elapsed / STEP));
      const dt = elapsed / steps;

      for (let step = 0; step < steps; step += 1) {
        for (const key of ["y", "scale"] as const) {
          const target = key === "y" ? targetY : targetScale;
          const offset = position.current[key] - target;
          velocity.current[key] +=
            ((-STIFFNESS * offset - DAMPING * velocity.current[key]) / MASS) *
            dt;
          position.current[key] += velocity.current[key] * dt;
        }
      }

      const settled =
        Math.abs(position.current.y - targetY) < 0.05 &&
        Math.abs(position.current.scale - targetScale) < 0.0005 &&
        Math.abs(velocity.current.y) < 0.05 &&
        Math.abs(velocity.current.scale) < 0.0005;

      if (settled) {
        position.current = { y: targetY, scale: targetScale };
        velocity.current = { y: 0, scale: 0 };
      }

      setPose({ ...position.current });
      if (!settled) frame = requestAnimationFrame(tick);
    };

    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [targetY, targetScale, reduced]);

  return pose;
}

/** Tracks `prefers-reduced-motion` without touching `window` during render. */
export function useReducedMotion() {
  const [reduced, setReduced] = useState(false);

  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => setReduced(query.matches);
    sync();
    query.addEventListener("change", sync);
    return () => query.removeEventListener("change", sync);
  }, []);

  return reduced;
}

/**
 * Static data and geometry transcribed from Bencho's "Toast stack" block.
 *
 * Bencho lays the widget out at a fixed 300 px width with 64 px rows. The
 * source's own defaults are peek 14, gap 10 and corner 20; the catalog preview
 * may pass other values, but the block ships with these.
 */

export type ToastKind = "success" | "info" | "error" | "warning";

export type Toast = {
  id: number;
  kind: ToastKind;
  title: string;
  body: string;
  action?: string;
};

export const TOAST_WIDTH = 300;
export const TOAST_HEIGHT = 64;

/** Toasts kept in the stack; the third one's contents are never painted. */
export const SHOWN = 3;

/** How much of each tucked toast shows below the front one. */
export const PEEK = 14;

/** Space between rows once the stack fans out. */
export const GAP = 10;

/** Corner radius, exposed to the block as `--tst-r`. */
export const CORNER = 20;

/**
 * Bencho's single shared spring: stiffness 380, damping 34, mass 1. The catalog
 * copy shows 320 / 30, but the shipped component is the source of truth.
 */
export const SPRING = {
  type: "spring",
  stiffness: 380,
  damping: 34,
  mass: 1,
} as const;

/** Exit tween, 220 ms with an ease-in curve. */
export const EXIT_MS = 220;

/** Closed-stack container height: 3 × 64 + 2 × 10. */
export const STACK_HEIGHT = SHOWN * TOAST_HEIGHT + 2 * GAP;

/** Front toast plus the peeks behind it. */
const CLOSED_HEIGHT = TOAST_HEIGHT + 2 * PEEK;

export const PRESETS: readonly Omit<Toast, "id">[] = [
  {
    kind: "error",
    title: "Payment declined",
    body: "Try another card.",
    action: "Retry",
  },
  {
    kind: "info",
    title: "Kai joined your bench",
    body: "They can comment and copy.",
  },
  {
    kind: "success",
    title: "brand-kit.zip uploaded",
    body: "Saved to Launch week.",
  },
  {
    kind: "warning",
    title: "Storage is 92% full",
    body: "Exports pause at the limit.",
  },
  {
    kind: "success",
    title: "Block saved",
    body: "Swipe deck is in Favourites.",
  },
];

export type Pose = { y: number; scale: number };

/** Tucked: depth 0 is front, capped at 2 so extra rows share the back slot. */
export function closedPose(depth: number): Pose {
  const capped = Math.min(depth, SHOWN - 1);
  return {
    y: (STACK_HEIGHT - CLOSED_HEIGHT) / 2 + (SHOWN - 1 - capped) * PEEK,
    scale: 1 - capped * 0.05,
  };
}

/** Fanned out: every row sits at full size, the front one lowest. */
export function openPose(depth: number): Pose {
  return {
    y: (SHOWN - 1 - depth) * (TOAST_HEIGHT + GAP),
    scale: 1,
  };
}

