}

/** The four kind icons, drawn from Bencho's own paths (Lucide geometry). */
export function ToastIcon({ kind }: { kind: ToastKind }) {
  switch (kind) {
    case "success":
      return (
        <Glyph>
          <circle cx="12" cy="12" r="10" />
          <path d="m9 12 2 2 4-4" />
